window.COURSE = {"title":"国际知识产权","updated":"2026-09-23","modules":[{"title":"国际规则全景","subtitle":"从商业问题找到条约","color":"blue"},{"title":"跨境保护的基本原则","subtitle":"品牌与技术出海","color":"blue"},{"title":"版权与罗马公约","subtitle":"一首歌背后的多层权利","color":"violet"},{"title":"数字传播与公共利益","subtitle":"授权、表演与无障碍阅读","color":"violet"},{"title":"申请程序与新议题","subtitle":"国际申请与传统知识","color":"orange"},{"title":"芯片保护与制度成败","subtitle":"保护对象、证据与产业现实","color":"orange"},{"title":"TRIPS的形成与执行","subtitle":"贸易谈判如何改变规则","color":"teal"},{"title":"创新与社会福利","subtitle":"评估保护的收益与代价","color":"teal"}],"units":[{"id":"k01","module":0,"pages":[9,12,18],"title":"国际条约解决什么商业问题","goal":"区分跨境保护、标准协调与程序合作。","body":["公司走出本国，会遇到不同的申请制度、保护标准和维权方式。条约让成员在一些问题上遵守共同规则。","条约的作用分三类：保障符合条件的外国主体获得保护，约定基本标准，简化申请与合作流程。不同条约侧重点不同。","共同规则保留了不少国内法差异。做出海方案，仍要明确目标市场、权利类型和使用行为。"],"kind":"tree","diagram":[["跨境经营","在哪些市场经营"],["保护待遇","外国企业能否获得保护"],["实体标准","最低应保护哪些权利"],["程序合作","怎样减少重复手续"]],"scenario":"一家音频设备公司准备同时销售硬件、使用品牌名并推出配套音乐App。团队想找一份条约，一次性解决三个市场的全部问题。","question":"下列哪些工作应纳入出海方案？","options":[{"text":"先销售再研究规则，因为条约只约束政府，与经营无关","why":"政府实施条约会影响企业申请、许可与维权。"},{"text":"按技术、商标和音乐内容分别识别权利与相关规则","why":"同一产品包含不同权利，需要分别识别。"},{"text":"结合目标市场法律核对申请与许可要求","why":"国际协调并未消除当地要求。"},{"text":"仅寻找一份条约，代替三个市场的法律调查","why":"错误地把国际协调当成完全统一。"}],"correct":[1,2],"sources":["paris","wto"],"note":"","label":"规则与应用"},{"id":"k02","module":0,"pages":[15,16,17],"title":"条约家族：先看保护对象","goal":"能把业务需求放进相应条约家族。","body":["工业产权包括专利、商标、外观设计等，巴黎公约提供基础框架。版权与邻接权则分别关注作品以及表演、录音制品、广播等。","商标与专利还有国际申请和程序协调工具。马德里体系、尼斯分类、商标法条约与PCT，解决的问题并不相同。","WIPO与WTO是机构，巴黎、伯尔尼、TRIPS等是条约或协定。先分清组织与法律文件，再查具体规则。"],"kind":"tree","diagram":[["国际知识产权","按业务识别"],["工业产权","技术、品牌、设计"],["版权及邻接权","作品、表演、录音、广播"],["申请程序","马德里、PCT等"],["机构","WIPO、WTO"]],"scenario":"一家奶茶品牌在海外申请品牌标识，同时为原创广告音乐购买许可。经理想用PCT提交品牌申请。","question":"你会怎样调整方案？","options":[{"text":"尼斯分类本身能授予国际商标权","why":"分类不等于注册或授予权利。"},{"text":"向WTO申请注册全部品牌资产","why":"WTO不负责企业商标注册。"},{"text":"商标采用相应商标申请渠道，音乐另核版权与邻接权许可","why":"业务对象不同，应拆开处理。"},{"text":"PCT同时办理品牌商标和音乐版权登记","why":"PCT是专利国际申请程序。"}],"correct":[2],"sources":["pct","paris"],"note":"","label":"规则与应用"},{"id":"k03","module":0,"pages":[19,20,22,23],"title":"巴黎公约：一个持续演变的联盟","goal":"理解加入、修订文本和成员资料的用途。","body":["巴黎公约于1883年订立，经过多次修订，形成工业产权跨境保护的重要基础。它建立联盟，并设置大会、执行委员会和国际局等机制。","旧课件的成员数和各国加入日期，是理解条约演变的资料，不能自动当作当前名单。分析两国之间的关系，还要看生效日期、适用文本与保留。","签署、批准或加入、生效不是同一动作。不能看到一国签名就认为所有修订条文已对其生效。"],"kind":"flow","diagram":[["谈判与签署","形成文本"],["批准或加入","表达受约束的同意"],["对该国生效","核对时间与条件"],["适用关系","核对文本及保留"]],"scenario":"企业2019年的培训资料列了某市场的条约状态。2026年出海预算会上，法务发现该国后来加入了新文本。","question":"最合理的下一步是什么？","options":[{"text":"直接用旧名单，成员身份一旦确定就不会变化","why":"成员情况与适用文本可能更新。"},{"text":"以最新文本公布日作为所有国家共同生效日","why":"公布或通过不等于对每一国生效。"},{"text":"只看该国是否参加过谈判","why":"参加谈判并不等于承担全部条约义务。"},{"text":"核对相关条文对该国生效的日期及适用关系","why":"时间和文本可能影响具体法律结论。"}],"correct":[3],"sources":["paris"],"note":"","label":"规则与应用"},{"id":"k04","module":0,"pages":[15,21,60,77],"title":"有约束力，不等于容易强制执行","goal":"避免把执行困难误读为没有法律义务。","body":["条约是否对当事国有约束力、争端由谁裁判、判决怎样执行，是三个不同问题。","巴黎公约对国际法院争端条款允许保留；这不等于公约全部义务都是自愿遵守。国际法院争讼判决对案件当事方有约束力。","比较WIPO条约与WTO机制，应比较争端处理和执行渠道，而不能简单贴上“无效／有效”的标签。"],"kind":"flow","diagram":[["法律义务","应当做什么"],["管辖与保留","由谁处理争端"],["执行机制","如何促成履行"]],"scenario":"出口商收到顾问意见：“该条约没有强力制裁，因此外国政府无需履行任何条款，企业也无需考虑国内实施法。”","question":"这份意见最关键的问题是什么？","options":[{"text":"把履行机制强弱与法律义务是否存在混为一谈","why":"两者需要分别判断。"},{"text":"没有把所有条约都当成国内直接适用法","why":"条约国内适用还受各法域制度影响。"},{"text":"没有建议企业自己直接向WTO起诉对手","why":"企业通常不能作为WTO争端当事方。"},{"text":"承认各国存在保留，因此结论必然正确","why":"保留范围需具体核对，不能扩展到全部条款。"}],"correct":[0],"sources":["paris","icj"],"note":"纠正原课件第21页：缺乏强制执行机制不能推出“国际法院判决不具约束力”。","label":"规则与应用"},{"id":"k05","module":1,"pages":[24],"title":"工业产权：一件商品可能有多层保护","goal":"从产品识别技术、标识、外观和竞争行为。","body":["一台咖啡机的技术方案、产品外观、品牌名和门店商号，可能对应不同保护。巴黎公约的工业产权概念还包括制止不正当竞争。","条约列出保护对象，不代表某件商品天然取得所有权利。各项权利仍要符合对应条件。","原课件提到公约未单列商业秘密。不能据此推断商业秘密在任何制度下都不受保护；还要看其他条约和国内法。"],"kind":"tree","diagram":[["咖啡机业务","资产拆分"],["技术","专利或实用新型"],["外观","工业品外观设计"],["标识","商标、商号"],["经营秩序","制止混淆与虚假宣传"]],"scenario":"一家企业发现竞品外壳相似、品牌名称接近，且宣传页声称自己的产品就是原厂升级款。","question":"哪些信息应优先分别调查？","options":[{"text":"只申请一个专利，就覆盖品牌名与广告陈述","why":"专利不自动包办其他保护。"},{"text":"外观权利状态、标识混淆以及宣传是否失实","why":"需要针对不同客体和行为建立证据。"},{"text":"只比较售价；低价即构成侵犯工业产权","why":"低价不是这些侵权行为的充分条件。"},{"text":"只证明自己先开业，就能排除所有竞争产品","why":"先开业不能替代各类权利要件。"}],"correct":[1],"sources":["paris"],"note":"","label":"规则与应用"},{"id":"k06","module":1,"pages":[25,26],"title":"国民待遇：合格外国主体的保护待遇","goal":"区分外国身份与国内主体同样需要满足的要求。","body":["国民待遇要求成员对符合条件的其他成员国国民给予不低于本国国民的相应保护。它并不保证申请一定成功。","非成员国国民，如在成员国有住所或真实、有效的工商业营业所，也可能按巴黎公约第3条获得相应待遇。","关键是核实资格连接点，不只看护照，也不能把纸面注册自动等同于真实、有效营业所。"],"kind":"flow","diagram":[["成员国国民？","核对国籍"],["否则看连接点","住所或真实有效营业所"],["满足资格","主张相应国民待遇"],["具体申请","仍须满足实体条件"]],"scenario":"公司创始人来自非成员国，但在成员国X有真实经营的工厂。向成员国Y申请工业产权时，Y方仅因创始人国籍拒绝一切保护。","question":"哪项分析最准确？","options":[{"text":"国民待遇意味着Y必须接受任何商标","why":"待遇与具体注册条件不同。"},{"text":"公司必须先把工厂迁到Y才能提出保护请求","why":"不能把请求保护国营业所作为一般前提。"},{"text":"应核对第3条的主体与营业所条件，不能只凭国籍排除","why":"公约还规定视同成员国国民的资格连接点。"},{"text":"只要有X国邮箱，就必然满足第3条","why":"邮箱不能证明住所或真实有效营业所。"}],"correct":[2],"sources":["paris"],"note":"","label":"规则与应用"},{"id":"k07","module":1,"pages":[27,28,29],"title":"待遇平等与商标按原样保护","goal":"把程序要求、形式接受与实体驳回分开。","body":["外国申请人仍可能面对代理人、送达地址等程序安排，国民待遇并不排除公约允许的程序规则。","商标按原样保护规则针对原属国正式注册商标，但有条件和保留。它不是“本国注册后，国外一定注册”。","他人在先权利、缺乏显著性、通用描述、违反公共秩序或欺骗公众等，可能成为公约所列驳回理由。"],"kind":"flow","diagram":[["原属国正式注册","核对适用前提"],["按原样申请保护","保留原有形式"],["检查列明事由","在先权利、显著性等"],["当地决定","不保证获准"]],"scenario":"饮料公司在原属国注册“纯天然果汁”文字标识，拟在另一成员国用于实际含人工香精的饮料。代理人指出描述性和误导风险。","question":"哪项建议合理？","options":[{"text":"原属国证书可排除任何实体驳回","why":"忽略公约明确保留的事由。"},{"text":"只要聘请当地代理，就必然获准","why":"代理解决程序问题，不保证实体条件。"},{"text":"国民待遇使该公司可以适用原属国所有审查标准","why":"保护国仍适用其相关制度。"},{"text":"核对按原样保护条件，并评估描述性与误导性驳回事由","why":"原属国注册不能消除列明的拒绝保护理由。"}],"correct":[3],"sources":["paris"],"note":"","label":"规则与应用"},{"id":"k08","module":1,"pages":[30],"title":"优先权：跨境申请的日期优势","goal":"识别首次申请与后续申请之间的关系。","body":["符合条件的首次正规申请，可以作为后续向其他成员国申请时主张优先权的基础。申请人或权利继受人需要按要求主张并证明。","后续申请中受首次申请支持的相同主题，可以获得首次申请日的优势。后来新增的技术内容，不能仅凭同一项目名称全部追溯。","优先权给企业准备翻译、资金和市场计划的时间，但不会自动授予外国权利。"],"kind":"flow","diagram":[["首次申请","记下日期和内容"],["海外准备","翻译、市场与资金"],["后续申请","按期限主张"],["主题核对","哪些内容获首次支持"]],"scenario":"电池企业首次申请披露结构A，4个月后新增控制算法B；8个月后在外国申请A+B并主张首次优先权。","question":"预算会上哪项表述最稳妥？","options":[{"text":"应分别核对A和B是否受到首次申请支持，不能一概追溯","why":"新增主题的优先权需要单独判断。"},{"text":"项目名称相同即可让A和B都追溯","why":"名称相同不能替代内容支持。"},{"text":"8个月已超过所有工业产权的优先权期限","why":"专利通常期限为12个月。"},{"text":"主张优先权就不必再办理外国申请","why":"必须有后续申请及相应手续。"}],"correct":[0],"sources":["paris"],"note":"","label":"规则与应用"},{"id":"k09","module":1,"pages":[31,32],"title":"优先权期限：技术12个月，商标与外观6个月","goal":"在产品上市计划里分别安排不同权利的时间。","body":["巴黎公约规定：专利与实用新型通常为12个月；工业品外观设计与商标通常为6个月。申请当日不计入期限。","同一个产品的技术、品牌和外观可能同日首次申请，却有不同的海外优先权安排。不要把产品当成一个统一截止日。","历史文本的期限曾改变，学习现行通常规则时要与修订史分开。实际届满还要核对法定假日等计算规则。"],"kind":"timeline","diagram":[["首次申请","技术与品牌同日提交"],["6个月","商标、外观设计通常期限"],["8个月","本题海外决策时间"],["12个月","专利、实用新型通常期限"]],"scenario":"一家智能水杯企业在成员国A首次申请发明专利和商标，8个月后拟向成员国B提交对应申请。假定资格和主题相同，且不考虑特殊救济。","question":"仅判断通常期限，哪些结论成立？","options":[{"text":"商标超期意味着品牌以后永远不能申请注册","why":"失去优先权不等于永久失去申请机会。"},{"text":"专利仍可能在12个月期限内","why":"期限条件可能满足，还需检查其他条件。"},{"text":"商标已经超出6个月通常期限","why":"不能按通常期限主张这次首次申请的优先权。"},{"text":"两项都适用12个月，因为它们属于同一产品","why":"期限取决于权利类型。"}],"correct":[1,2],"sources":["paris"],"note":"","label":"规则与应用"},{"id":"k10","module":1,"pages":[33,34],"title":"地域性与权利独立：海外授权另作判断","goal":"避免把本国权利或优先权当成全球许可证。","body":["知识产权保护通常具有地域性。相同发明在不同成员国获得的专利彼此独立，一国授权不能强迫另一国授权。","跨境电商让行为、消费者和损害分散在多个地方。分析要找销售、进口、广告投放等连接点，而不是只看服务器在哪。","课件讨论法院个案中的域外适用。这是存在条件和法域差异的问题，不是“互联网让地域性失效”。"],"kind":"split","diagram":[["日期问题","能否有效主张优先权"],["授权问题","目标市场能否获得权利"],["行为问题","销售、进口或传播发生在哪"],["争议问题","哪国法院与法律有联系"]],"scenario":"企业拥有A国专利，也在B国按时主张优先权，但B国还未授权。销售经理称可仅凭A国证书在B国要求所有竞品下架。","question":"哪项判断最合理？","options":[{"text":"服务器放在A国，销售到B国也与B国无关","why":"不能忽略目标市场行为连接点。"},{"text":"B国未授权可证明A国专利必然无效","why":"两国专利判断相互独立。"},{"text":"核对B国权利状态及相关保护规则，A国授权本身不足","why":"地域性与权利独立要求单独分析。"},{"text":"只要优先权有效，B国专利就自动授权","why":"混淆申请日期和授权。"}],"correct":[2],"sources":["paris"],"note":"","label":"规则与应用"},{"id":"k11","module":1,"pages":[35],"title":"不正当竞争：混淆、贬损与误导","goal":"识别没有复制技术也可能出现的竞争风险。","body":["巴黎公约第10条之二要求有效制止不正当竞争，关注工商业活动中违反诚实惯例的行为。","课件列出三类重点：使公众混淆，作虚假陈述损害竞争者信誉，以及让公众误解商品特征的标记或陈述。","企业比较广告可以讨论真实差异，但应核实证据与表达方式。低价、竞争激烈本身不等于不正当竞争。"],"kind":"tree","diagram":[["竞争宣传","检查信息和受众理解"],["混淆","让消费者误认关联"],["虚假贬损","损害对手信誉"],["误导说明","误认性质、质量或数量"]],"scenario":"新品牌广告使用与老品牌极近的包装，并在未检测的情况下称“老品牌含违禁物，我们才是唯一安全选择”。","question":"哪些问题值得分别审查？","options":[{"text":"没有依据的贬损是否损害对手信誉","why":"需结合真实性、传播和相关法律判断。"},{"text":"只要广告未复制专利技术就不涉及知识产权体系","why":"忽视不正当竞争保护。"},{"text":"新品牌定价更低就已经足以证明违法","why":"价格低本身不构成这里的充分依据。"},{"text":"包装是否造成来源或关联混淆","why":"对应公约重点禁止的混淆行为。"}],"correct":[3,0],"sources":["paris"],"note":"","label":"规则与应用"},{"id":"k12","module":2,"pages":[15,36],"title":"版权与邻接权：先把权利人拆开","goal":"一份授权合同未必覆盖全部音乐使用。","body":["作品、表演和录音制品是不同层次。一首商业歌曲可能涉及词曲作品权利、歌手或乐手的表演相关权利，以及录音制品制作者权利。","伯尔尼公约关注文学艺术作品；罗马公约、WPPT等关注相关权利。实际许可范围还要看当地法和合同。","购买歌曲文件、购买播放设备、取得某一层授权，均不能当然推定已经拿到广告使用所需的全部许可。"],"kind":"tree","diagram":[["广告使用一首歌","逐层检查"],["词曲","作品权利"],["演唱演奏","表演者相关权利"],["具体录音","录音制作者权利"]],"scenario":"品牌买到一段录音的商业使用许可，但合同明确不包含词曲作品权利，计划剪成广告并投放多个市场。","question":"签约负责人应怎样处理？","options":[{"text":"另行核对词曲等缺失权利及投放范围","why":"已取得的录音许可不能覆盖合同排除的层次。"},{"text":"只要付过一次钱，就可以忽略明确排除条款","why":"付款次数不决定授权范围。"},{"text":"把音乐压缩成低码率即可消除权利问题","why":"格式变化不当然消除受保护使用。"},{"text":"只标注歌名即可补足全部许可","why":"署名不等于取得许可。"}],"correct":[0],"sources":["berne","rome","wppt"],"note":"","label":"规则与应用"},{"id":"k13","module":2,"pages":[36],"title":"三步检验：例外也有边界","goal":"不能仅凭“教学用途”免除所有复制责任。","body":["伯尔尼公约第9条第2款针对复制权例外设置条件：某些特殊情形、不与作品正常利用冲突、不不合理地损害作者合法利益。","三步检验约束例外的设计与适用理解，不是一张能直接代替国内法的通行证。具体案件先找适用的国内例外，再看相关条件。","判断商业方案，要问范围有多大、是否替代购买或许可市场、利益损害是否合理。"],"kind":"flow","diagram":[["特殊情形","边界明确吗"],["正常利用","会替代销售或许可吗"],["合法利益","损害是否不合理"]],"scenario":"收费培训机构准备把整本热门教材扫描到学员群，称“每位学员都用于学习，所以肯定免责”。未获许可，当地是否有适用例外尚未核实。","question":"哪项评估最准确？","options":[{"text":"三步检验只需满足任意一步","why":"相关条件不是任选其一。"},{"text":"先查国内例外，整本复制还可能影响教材正常市场","why":"教学标签不是充分条件。"},{"text":"只要收费不单列教材费，就必然不影响市场","why":"交易方式不能排除替代效应。"},{"text":"必须先证明作者实际破产，才能认定不满足条件","why":"损害判断不以作者破产为前提。"}],"correct":[1],"sources":["berne"],"note":"","label":"规则与应用"},{"id":"k14","module":2,"pages":[37,40,42,45],"title":"罗马公约：三类对象与最低保护","goal":"区分作品、录音、表演及广播的保护层次。","body":["罗马公约保护表演者、录音制品制作者和广播组织，由WIPO、UNESCO及ILO共同管理。","它提供的是相应国际最低保护框架。20年的最低期限不能直接当作所有国家、所有相关权利的实际期限；后续条约和国内法可能更长。","分析录音、表演或广播，要先确认保护对象，再核对连接点、行为、例外与期限起算。"],"kind":"tree","diagram":[["罗马公约","最低保护框架"],["表演者","表演及相关行为"],["录音制作者","录音复制等"],["广播组织","信号转播与固定等"]],"scenario":"制作公司想使用一段已录制25年的音乐节目，采购员认为罗马公约最低20年已过，因此全部权利均可免费使用。","question":"你应提出什么异议？","options":[{"text":"超过20年后所有国家均不许继续保护","why":"国际最低期限允许国内更高保护。"},{"text":"只要没有原始磁带，任何复制均不受限制","why":"载体是否保存不决定权利存续。"},{"text":"要分别查作品、表演、录音或广播的适用期限及当地法","why":"最低标准并非统一实际期限。"},{"text":"只检查节目视频文件的创建日期即可","why":"文件生成时间不等于各项法定起算事件。"}],"correct":[2],"sources":["rome"],"note":"","label":"规则与应用"},{"id":"k15","module":2,"pages":[38,39,41],"title":"保护连接点：外国录音和表演如何进入体系","goal":"将主体、固定地、出版地与广播连接点分开检查。","body":["罗马公约对录音制品设置制作者国籍、首次固定地、首次出版地等连接点，并允许特定保留。非成员国首次出版后30日内在成员国出版，可能按同时出版规则处理。","广播连接点包括总部和发射台所在地，缔约方可以作规定范围内的保留。表演可通过发生地、受保护录音或广播取得连接。","因此“外国内容”不是一个完整法律结论，还要查成员关系、具体条件与保留。"],"kind":"flow","diagram":[["识别对象","录音、表演或广播"],["查连接点","国籍、地点或出版"],["查时间","是否满足同时出版"],["查保留","当地接受哪些标准"]],"scenario":"录音公司先在非成员国发行，20天后在罗马公约成员国发行。目标保护国也是成员，但代理人尚未核查其保留。","question":"最合理的意见是什么？","options":[{"text":"首次在非成员国发行就永久失去所有公约保护","why":"忽略同时出版规则。"},{"text":"20天意味着所有版权、商标和专利均获得保护","why":"不同对象有不同制度。"},{"text":"目标国是否作保留不影响分析","why":"公约允许对部分连接标准作保留。"},{"text":"30日规则可能相关，仍须检查目标国保留等条件","why":"不能只凭一个连接事实保证结果。"}],"correct":[3],"sources":["rome"],"note":"","label":"规则与应用"},{"id":"k16","module":2,"pages":[40,42,43],"title":"许可要对应行为：录制、复制和传播不同","goal":"从内容生产流程识别授权缺口。","body":["罗马公约分别处理未经同意的现场表演广播或传播、未固定表演的录制，以及特定情形下的固定物复制。授权录制不当然等于授权所有后续用途。","广播组织的最低权利涉及转播、固定、一定复制，以及收费入场场所向公众传播电视广播。它们不能直接等同于所有网络传播场景。","合同应写清录制、剪辑、复制、投放渠道、地区和期限。是否必须取得特定许可，仍要结合适用制度。"],"kind":"flow","diagram":[["现场表演","谁同意演出"],["录制","是否允许固定"],["复制与剪辑","许可是否覆盖"],["对外投放","渠道、地区与期限"]],"scenario":"歌手合同只允许品牌录制活动并作内部存档。品牌把视频重新剪辑成跨境付费广告，还保留了电视台转播画面。","question":"下列哪项行动最必要？","options":[{"text":"核对歌手、节目及广播素材涉及的各项权利与用途","why":"实际行为超出内部存档，应逐层核查。"},{"text":"有录制许可，就不必再看用途限制","why":"忽略许可范围。"},{"text":"广告片长度短于原活动，就自动免责","why":"长度不是通用免责标准。"},{"text":"去掉电视台标识就能消除广播相关权利","why":"去标识不当然消除权利，且可能增加其他问题。"}],"correct":[0],"sources":["rome"],"note":"","label":"规则与应用"},{"id":"k17","module":2,"pages":[44,55],"title":"允许使用与支付报酬：两种不同机制","goal":"区分事先授权权与合理报酬请求。","body":["某些制度要求事先得到权利人同意；另一些特定使用场景，可能适用支付合理报酬的机制。不能把所有付费使用都叫成同一种许可。","罗马公约第12条涉及商业录音用于广播或向公众传播的一次性合理报酬，受相关保留和国内实施影响。北京条约在规定范围内也允许报酬机制替代授权权。","企业付款前，应确认谁有权收取、付款覆盖何种使用，以及其他层权利是否另需许可。"],"kind":"split","diagram":[["事先授权","先取得同意，再按范围使用"],["法定报酬机制","核实适用条件及支付义务"],["合同价款","只覆盖合同约定权利"],["其他权利","仍须分别清理"]],"scenario":"酒店向某录音集体管理组织支付背景音乐费用，就打算把同一录音用于线上促销视频。","question":"哪项说法正确？","options":[{"text":"只要酒店播放合法，广告视频一定合法","why":"使用行为不同，不能直接外推。"},{"text":"酒店播放付费未必覆盖广告视频，应核对不同用途和权利","why":"报酬机制和合同的覆盖范围均有限。"},{"text":"付给任何一家组织即可覆盖全球全部用途","why":"组织代表范围和地域均需确认。"},{"text":"支付报酬意味着酒店取得录音所有权","why":"使用费不等于权利转让。"}],"correct":[1],"sources":["rome","beijing"],"note":"","label":"规则与应用"},{"id":"k18","module":2,"pages":[46,47],"title":"罗马公约例外与非传统表演","goal":"区分成员可以规定的例外与企业已经获得的免责。","body":["罗马公约允许成员对私人使用、时事报道短片段、广播临时固定、教学或科研等设置例外。允许国内立法设置，不等于商业主体可不经检查自行套用。","公约还允许把保护扩展到不表演文学艺术作品的艺人。杂技、魔术、体育或电竞在不同制度下的客体和保护路径未必相同。","现实中应分别识别活动、表演、录制节目和赛事信号，避免用一个名称概括所有权利。"],"kind":"flow","diagram":[["使用目的","私人、报道、教学还是营销"],["当地例外","是否实际设有规则"],["具体条件","范围、来源和传播方式"],["结论","满足条件才可能适用"]],"scenario":"企业培训经理把电视节目整段复制到付费公开培训平台，认为罗马公约出现“教学”二字就允许。","question":"最合理的回应是什么？","options":[{"text":"将平台改成会员制即可必然构成私人使用","why":"会员制不等于私人使用。"},{"text":"所有例外只适用于纸质作品","why":"相关公约恰恰涉及表演、录音及广播。"},{"text":"需要核对国内实施规则、用途与传播范围，不能自动免责","why":"条约允许设置例外不等于任何教学使用均合法。"},{"text":"只要课程有老师授课，就无需再核对","why":"缺少例外要件判断。"}],"correct":[2],"sources":["rome"],"note":"","label":"规则与应用"},{"id":"k19","module":2,"pages":[48,49],"title":"℗标记：形式手续与权利本身","goal":"避免把标记缺失当成免费使用依据。","body":["℗通常与录音制品权利声明有关。罗马公约和日内瓦录音制品公约的相应规定，处理的是某国要求形式手续时怎样满足，而不是所有作品一律必须贴标。","声明可能涉及首次出版年份、制作者等信息。它有助于识别，但不能单独证明全部许可范围。","WPPT进一步规定，享有和行使其规定权利不以履行形式手续为条件。没有看到℗，不能据此推断无权利。"],"kind":"split","diagram":[["有℗标记","提供权利识别线索"],["没有℗标记","不能自动推定无权利"],["当地要求","是否存在形式条件"],["授权核对","主体与范围仍需确认"]],"scenario":"广告公司从旧唱片转录音乐，包装未见℗，但能识别制作公司和歌手。客户要求当天上线。","question":"应如何判断？","options":[{"text":"无℗即可商业使用，署名也不必","why":"将形式手续误当权利存在的唯一条件。"},{"text":"自己添加℗即可成为权利人","why":"单方标注不能创设他人的权利。"},{"text":"仅联系唱片销售商就足够","why":"销售商未必有相关授权权。"},{"text":"继续核查权利与适用规则，不能因缺标记推定免费","why":"标记缺失不等于权利不存在。"}],"correct":[3],"sources":["rome","phonograms","wppt"],"note":"原课件第49页“须载有声明”需加条件：不能把特定形式手续规则写成所有录音获得保护的普遍前提。","label":"规则与应用"},{"id":"k20","module":3,"pages":[49,50,51],"title":"日内瓦录音制品公约：制止商业盗录","goal":"区分保护对象、实施方式与强制许可条件。","body":["1971年订立、1973年生效的公约，针对录音制品未经同意复制、为发行目的进口及向公众发行等问题。这里的录音制品是纯声音固定物。","成员可通过版权、专门权利、反不正当竞争或刑事制裁等方式实施。最低期限不等于所有法域实际期限。","课件所列强制许可条件必须同时满足：仅为教学或科研、限定本国复制且不扩展出口、支付合理报酬。"],"kind":"flow","diagram":[["教学或科研","检查真实用途"],["国内复制","不能扩展为出口许可"],["合理报酬","按适用安排支付"],["共同满足","再核其他法律条件"]],"scenario":"出版商拟依教学强制许可复制录音，计划在本国出售一部分，并向海外培训机构出口一半。假定本国存在相应许可制度。","question":"方案最明显的问题是什么？","options":[{"text":"把国内教学复制许可扩展到出口","why":"公约所列条件明确限制出口。"},{"text":"只要已付款，就不受任何用途限制","why":"报酬不能替代其他条件。"},{"text":"先出口后补报酬即可满足全部条件","why":"付款时间不能消除出口范围问题。"},{"text":"公约仅针对电影画面，因此无需分析","why":"公约关注纯声音录音制品。"}],"correct":[0],"sources":["phonograms"],"note":"","label":"规则与应用"},{"id":"k21","module":3,"pages":[52],"title":"WPPT：数字环境下的录音与表演","goal":"认识技术措施和权利管理信息的独立风险。","body":["WPPT于1996年通过、2002年生效，关注表演者和录音制品制作者在数字环境中的权利。课件强调至少50年保护和不以形式手续为条件。","条约要求对规避相关有效技术措施，以及特定删除、修改权利管理信息等行为提供法律保护或救济；具体责任要件由适用规则判断。","内容授权、技术访问和元数据管理应一起核对。拿到文件不代表可以任意破除保护或删除权利信息。"],"kind":"flow","diagram":[["取得素材","来源与许可"],["技术访问","是否绕过保护措施"],["元数据信息","是否删除权利信息"],["实际使用","渠道与用途是否被覆盖"]],"scenario":"音乐App拥有部分曲目的在线播放许可。工程师为了生成下载广告样片，绕过加密并批量删除权利人信息。","question":"哪些风险需要独立审查？","options":[{"text":"只要不改变旋律，就无任何风险","why":"复制传播方式及管理信息仍重要。"},{"text":"样片下载广告是否超出许可用途","why":"在线播放授权未必覆盖该行为。"},{"text":"技术措施及权利管理信息的相关法律要求","why":"这类行为可能有独立法律风险。"},{"text":"只要原先有一项许可，其他行为均免责","why":"将有限许可扩大为全面授权。"}],"correct":[1,2],"sources":["wppt"],"note":"","label":"规则与应用"},{"id":"k22","module":3,"pages":[53],"title":"北京条约：视听表演的经济权利","goal":"把演员表演与整部影视作品权利分开。","body":["北京条约于2012年通过，2020年4月28日生效，补充视听表演者的国际保护。课件列出固定表演的复制、发行、出租和向公众提供等权利。","演员出现在电影、剧集或音乐视频中，相关表演利益不应因已经录制就被忽略。","企业使用影视片段，要核查制片方授权链、表演者权利转移安排和当地实施法，不能仅凭一份演员同意代替全部作品权利。"],"kind":"tree","diagram":[["影视广告素材","权利链审查"],["作品及制作","制片方等授权"],["表演","演员等相关权利"],["音乐及其他素材","逐项核对"],["使用范围","平台、地区、期限"]],"scenario":"品牌得到主演同意使用其电影表演片段，却未联系制片方；广告含原片配乐。","question":"哪项建议最稳妥？","options":[{"text":"将片段裁成竖屏即可避免授权","why":"裁切不当然消除权利。"},{"text":"北京条约只保护声音录音，不涉及演员","why":"条约重点是视听表演。"},{"text":"同时核对电影、配乐及表演的授权链","why":"演员许可不自动覆盖其他主体权利。"},{"text":"主演同意即能代替制片方和作曲者","why":"不同主体与权利层次不可合并。"}],"correct":[2],"sources":["beijing"],"note":"","label":"规则与应用"},{"id":"k23","module":3,"pages":[54],"title":"精神权利：署名与表演完整性","goal":"理解正常剪辑和有损声誉的歪曲并非同一回事。","body":["北京条约涉及表演者身份表明和反对有损声誉的歪曲、篡改等精神权利，具体适用有条件。","正常制作中的剪辑、压缩、配音或格式处理，并不因发生了修改就自动构成对表演完整性的侵害。要看授权背景、变化性质和声誉影响等。","签署经济使用许可，也不意味着可以随意把演员表演改成具有误导性的商品背书。"],"kind":"split","diagram":[["正常制作处理","剪辑、压缩、格式适配"],["高风险修改","歪曲意思、损害声誉"],["署名问题","身份表示及适用例外"],["合同问题","约定用途与授权范围"]],"scenario":"经演员许可制作的访谈短片，品牌把“我没有使用过该产品”剪成“我使用过该产品”，并用作代言广告。","question":"哪项判断较准确？","options":[{"text":"合同写可剪辑，任何删改都合法","why":"一般编辑许可不必然涵盖误导背书。"},{"text":"所有视频剪辑都当然侵犯精神权利","why":"过度概括，正常制作处理并非一律侵害。"},{"text":"只要保留演员姓名就消除全部风险","why":"署名不能消除内容歪曲。"},{"text":"需审查超范围使用及歪曲表演等风险，不能以可剪辑概括免责","why":"删改改变了关键意思，与一般格式处理不同。"}],"correct":[3],"sources":["beijing"],"note":"","label":"规则与应用"},{"id":"k24","module":3,"pages":[55],"title":"报酬替代与保留：同一内容，不同市场","goal":"看到条约规则后还要查成员作出的选择。","body":["北京条约第11条涉及广播和向公众传播固定视听表演。缔约方在规定范围内可以采用合理报酬机制，或作特定限制与保留。","在相应保留情形和范围内，其他缔约方可以按条约安排限制待遇。因此跨国许可不能只看一个国家的模式。","先确认使用行为，再查目标市场的实施规则和保留，最后确定许可或支付路径。"],"kind":"flow","diagram":[["目标使用","广播或向公众传播"],["成员选择","授权、报酬及保留"],["国内实施","具体义务与主体"],["商业合同","地域与费用覆盖"]],"scenario":"流媒体集团准备把同一视听表演包卖到两个市场。业务员发现一地采用报酬机制，就认为另一地也可以先播后付。","question":"最合理的处理是什么？","options":[{"text":"按目标市场分别核对制度选择与保留","why":"一地模式不能直接推定另一地。"},{"text":"合同写全球使用就能改变成员国法律","why":"合同不能改写法律。"},{"text":"两个市场都是条约成员，所以每项机制必然相同","why":"条约允许某些选择与保留。"},{"text":"条约允许保留，因此全部权利均可忽略","why":"保留只能在相应范围内影响义务。"}],"correct":[0],"sources":["beijing"],"note":"","label":"规则与应用"},{"id":"k25","module":3,"pages":[56,57],"title":"马拉喀什条约：让阅读障碍者获得作品","goal":"识别受益人、无障碍格式和授权实体的边界。","body":["条约于2013年通过、2016年生效，要求设置相应版权限制或例外，便利盲人、视力障碍者或其他印刷品阅读障碍者获得作品。","它允许符合条件的无障碍格式版由授权实体跨境提供给另一缔约方的受益人或授权实体。不是任意平台向任何用户传播电子书的依据。","无障碍公益目标与商业电子书市场之间的边界，取决于受益人、主体资格和具体使用条件。"],"kind":"flow","diagram":[["确认受益人","是否符合条约定义"],["制作无障碍版","按例外及条件"],["授权实体","核对身份与职责"],["跨境交换","限定合格接收方"]],"scenario":"有声书平台拟把教材做成无障碍音频，先向合格受益人提供，随后将同一版本卖给全体付费会员，声称都受条约保护。","question":"哪些分析合理？","options":[{"text":"条约从不允许跨境交换","why":"条约恰有相关跨境安排。"},{"text":"先核对主体是否符合授权实体及相应规则","why":"平台自称无障碍不代表满足资格。"},{"text":"面向所有会员商业销售不能仅凭该条约正当化","why":"受益人和用途边界不能任意扩展。"},{"text":"只要格式是音频就必然适用","why":"格式不是唯一条件。"}],"correct":[1,2],"sources":["marrakesh"],"note":"","label":"规则与应用"},{"id":"k26","module":4,"pages":[16,58,59],"title":"商标程序协调：减手续，不保证注册","goal":"区分行政流程一致与实体标准一致。","body":["1994年商标法条约关注申请、变更、续展等程序协调。商标法新加坡条约于2006年通过、2009年生效，适应电子通信等发展。","新加坡条约适用于成员国内法可注册的相应标志，包括部分非传统标志。它不要求所有成员接受每一种声音、气味或全息商标。","国际分类和程序协调降低办理成本，但显著性、冲突在先权利等问题仍需目标市场评估。"],"kind":"split","diagram":[["程序协调","申请、变更、续展、救济"],["电子办理","通信方式更便利"],["非传统标志","先看当地可注册对象"],["实体审查","显著性与在先权利"]],"scenario":"香水公司想在多个新加坡条约成员国注册气味商标，代理人称成员身份意味着各国必须接受。","question":"哪项回应正确？","options":[{"text":"用尼斯分类号即可替代注册申请","why":"分类不授予商标权。"},{"text":"电子提交后就不再适用驳回理由","why":"提交方式不改变实体标准。"},{"text":"需逐国核对可注册标志范围及实体条件","why":"条约不创设各国接受所有非传统商标的一般义务。"},{"text":"成员国必须接受所有气味标志且免审查","why":"过度扩大条约作用。"}],"correct":[2],"sources":["singapore"],"note":"补充原课件第59页：程序协调不等于成员必须注册所有非传统商标。","label":"规则与应用"},{"id":"k27","module":4,"pages":[16,60],"title":"PCT：国际申请程序，不是世界专利","goal":"知道国际阶段与国家或地区阶段的分工。","body":["PCT于1970年订立、1978年生效。它提供国际申请、检索等合作程序，帮助申请人安排多市场专利布局。","国际阶段并不直接授予覆盖全球的专利。后续国家或地区主管机关仍按其法律决定授权。","国际初步审查意见的非约束性，也不等于PCT整个条约没有法律效力。预算中应区分国际阶段成本与后续国家阶段成本。"],"kind":"flow","diagram":[["国际申请","统一入口"],["国际检索等","了解可专利性信息"],["选择目标市场","成本与商业计划"],["国家或地区阶段","主管机关审查授权"]],"scenario":"机器人创业公司完成PCT申请，融资材料写“已取得全球专利”，并只为国际阶段预留费用。","question":"哪些修改必要？","options":[{"text":"补充目标市场后续申请、翻译及程序成本规划","why":"国际程序未消除后续投入。"},{"text":"保留全球专利说法，只缩小字体","why":"改变字号不能修正不实表述。"},{"text":"拿到国际检索报告就可停止所有后续手续","why":"报告不能替代国家或地区阶段。"},{"text":"把状态改为相应国际申请状态，避免声称已全球授权","why":"申请不等于授权。"}],"correct":[3,0],"sources":["pct"],"note":"原课件把PCT归为“软法”的概括不宜直接沿用；应区分条约效力与审查意见效力。","label":"规则与应用"},{"id":"k28","module":4,"pages":[17,61],"title":"WIPO与WTO：组织不是注册证书","goal":"理解条约管理与贸易争端平台的区别。","body":["巴黎与伯尔尼体系的国际局后来合并，WIPO承接相关国际管理职能。WIPO管理多项知识产权条约和国际申请服务。","WTO于1995年成立，TRIPS属于其法律体系。它把知识产权最低标准和贸易争端机制联系起来。","组织名称不是企业权利证明。企业要知道自己正在办理国际申请、合同许可、国内诉讼，还是推动政府交涉。"],"kind":"split","diagram":[["WIPO","条约管理、国际申请服务等"],["WTO","贸易规则及成员间争端"],["国内主管机关","具体审查与登记"],["法院及其他机制","解决相应争议"]],"scenario":"企业认为海外仿冒严重，准备直接给WTO提交一份商标注册申请，并要求WTO命令竞争者赔偿。","question":"应如何纠正？","options":[{"text":"商标申请与企业维权应走相应渠道，WTO不是企业商标注册机关","why":"需区分机构职能与争端主体。"},{"text":"所有国际知识产权业务都只能找WTO","why":"忽略WIPO及国内体系。"},{"text":"WIPO和WTO只是同一机构的两个名称","why":"两者制度与职能不同。"},{"text":"拥有WIPO申请编号即能直接执行全球赔偿","why":"编号不等于全球可执行判决。"}],"correct":[0],"sources":["pct","wto"],"note":"","label":"规则与应用"},{"id":"k29","module":4,"pages":[62,63],"title":"遗传资源与传统知识：来源和惠益问题","goal":"把专利披露与其他资源合规分开。","body":["生物多样性公约关注保护、可持续利用及遗传资源惠益分享；文化多样性公约关注文化表达多样性。它们与知识产权相互影响，但目标不等同于专利或版权条约。","2024年WIPO遗传资源与相关传统知识条约的重点是特定专利申请披露要求，提高透明度、减少错误授权，并规定不溯及既往等安排。","条约通过不等于立即在全球实施。具体专利披露、资源取得与惠益分享义务，要分别核对适用制度和生效情况。"],"kind":"flow","diagram":[["研发材料来源","遗传资源及知识来源"],["专利申请","核对披露义务"],["资源利用","另查取得与惠益规则"],["适用时间","通过、生效与国内实施"]],"scenario":"护肤企业从传统药用植物知识出发研发配方，经理认为“在专利申请里写了来源”就完成所有资源取得与惠益分享合规。","question":"哪项判断正确？","options":[{"text":"传统知识与专利申请永远无关","why":"既可能涉及现有知识，也可能涉及披露。"},{"text":"披露、资源取得与惠益分享应分别核对，不能相互替代","why":"义务目的和依据不同。"},{"text":"公开来源就自动取得全部资源使用许可","why":"信息披露不等于取得授权。"},{"text":"2024年通过即代表所有国家已执行同一规则","why":"通过、生效与实施不同。"}],"correct":[1],"sources":["genetic"],"note":"","label":"规则与应用"},{"id":"k30","module":5,"pages":[64,65],"title":"布图设计：保护芯片的空间布局","goal":"区分布局、功能与制造技术。","body":["集成电路布图设计关注元件与连接线路的三维配置。它与芯片实现的抽象功能、算法或制造工艺不是同一保护对象。","课件以1989年华盛顿条约说明专门保护思路：设计投入可能很高，复制成本可能低，因此出现独立的制度安排。","企业应把布图版本、研发记录、权属协议与登记材料对应起来，不能只用“功能一样”证明复制布局。"],"kind":"split","diagram":[["布局","元件与连接的配置"],["功能","芯片实现什么"],["技术","制造方法与工艺"],["证据","版本、权属与比对"]],"scenario":"甲公司的电源芯片与乙公司的功能相同，但甲采用独立设计的不同布局。乙只凭功能一致主张布局被复制。","question":"目前最关键的判断是什么？","options":[{"text":"尺寸不同就绝不可能侵权","why":"尺寸不是唯一判断标准。"},{"text":"有登记证就无需识别受保护内容","why":"登记不能替代案件中的对象与范围分析。"},{"text":"需要识别受保护布局并比对，功能相同本身不足以证明复制","why":"保护对象决定证据方向。"},{"text":"功能相同必然侵犯布图设计权","why":"混淆功能和配置。"}],"correct":[2],"sources":["wto","case"],"note":"","label":"规则与应用"},{"id":"k31","module":5,"pages":[66],"title":"条约未生效，相关规则仍可能发挥作用","goal":"理解规则通过其他法律进入适用体系。","body":["华盛顿集成电路条约未生效，不意味着布局保护在世界范围不存在。TRIPS通过引用及补充安排规定了相关保护义务。","企业面对的直接制度还包括各国国内法。判断权利时，应检查适用法律、主体、保护条件与期间。","这也说明“某条约成败”和“某类权利有无保护”是两个问题。"],"kind":"flow","diagram":[["原条约","观察生效状态"],["其他协定","是否引用或补充"],["国内制度","如何实施保护"],["实际案件","适用具体条件"]],"scenario":"供应链负责人发现华盛顿条约没有生效，便计划复制供应商芯片布局，认为不会遇到权利障碍。","question":"哪项调查应先完成？","options":[{"text":"只核对原条约即可停止调查","why":"忽略其他法律来源。"},{"text":"只要供应商是外国企业就没有保护","why":"忽略待遇和主体条件。"},{"text":"签一份内部免责书就能排除第三方权利","why":"内部约定不能消灭第三方权利。"},{"text":"核对目标市场国内法与TRIPS相关保护安排","why":"原条约状态不能代替法律适用调查。"}],"correct":[3],"sources":["wto"],"note":"","label":"规则与应用"},{"id":"k32","module":5,"pages":[67,68,69,73],"title":"少登记、少诉讼：不能直接推出制度无用","goal":"把历史数据和产业判断分开。","body":["课件展示美国和中国台湾地区的历史登记数据，并讨论诉讼数量与产业结构。这些数字有特定时间范围和统计口径。","登记少可能与替代保护、产品周期、商业秘密策略或维权成本有关。它不能单独证明不存在侵权、保护没有价值或全部企业都不需要权利。","评估制度价值，可比较被复制风险、登记成本、技术更新速度及许可收益；课件“芯片不需要法律保护”的说法属于可争论观点。"],"kind":"tree","diagram":[["观察","登记或案件数量"],["可能原因","成本、周期、替代策略"],["缺失信息","风险与反事实"],["决策","结合企业具体业务"]],"scenario":"投资人看到课件中的历史登记数量，要求芯片团队停止所有布局保护预算；团队尚未评估被复制风险。","question":"哪个建议更稳妥？","options":[{"text":"补充企业风险、替代保护和成本收益数据再决定","why":"数量不足以推出预算归零。"},{"text":"登记少证明所有布局都无法获得保护","why":"没有这种推论关系。"},{"text":"诉讼少证明从未发生复制","why":"争议可能通过其他方式处理。"},{"text":"凡是有法律就应不计成本登记全部版本","why":"忽略商业价值与管理成本。"}],"correct":[0],"sources":[],"note":"原课件历史统计保留在逐页对照中，未作为现行数量或普遍结论使用。","label":"数据与观点辨析"},{"id":"k33","module":5,"pages":[70],"title":"锂电池保护芯片案：独创性需要证据链","goal":"理解具体布局、独创性说明与反证的联系。","body":["课件讨论最高人民法院（2019）知民终490号案件。布图设计的独创性判断应围绕具体配置展开，不能只讨论电路功能是否常见。","权利人对独创性作出合理说明后，反方可通过公认常规设计等材料提出反证；案件结论仍取决于证据和具体规则。","企业应保留设计过程、版本变更、研发投入与既有设计差异。对外披露多少信息和诉讼中如何证明，是需要分别处理的问题。"],"kind":"flow","diagram":[["确定布局","具体保护范围"],["说明独创性","配置与设计过程"],["检验反证","是否属于常规"],["综合判断","案件证据与规则"]],"scenario":"甲能提交登记、布局版本和设计说明，乙只说“电池保护功能早就有了”，没有提交常规布局证据。","question":"乙的论证主要缺口是什么？","options":[{"text":"案件中任何登记证都不能作为证据","why":"登记材料可以有证明作用。"},{"text":"没有针对具体布局及独创性说明提出有力反证","why":"抽象功能常见不等于具体配置常规。"},{"text":"必须先证明所有芯片都不能受保护","why":"这种要求过度且无关。"},{"text":"只要产品更便宜就已经构成反证","why":"价格不能证明布局常规。"}],"correct":[1],"sources":["case"],"note":"","label":"规则与应用"},{"id":"k34","module":5,"pages":[71],"title":"2026年新条例：先看施行日期","goal":"将新规内容与时间适用分开。","body":["2026年修订的中国集成电路布图设计保护条例已公布，施行日期为2026年10月15日。截至本课件核对日2026年9月23日，它尚未施行。","新条例规定独创性要求及登记相关安排；保护期为10年，自登记申请日或首次商业利用日中较早者起算，并有自创作完成起15年的上限。","跨越新旧法节点的项目应核对过渡与适用问题，不能因为读到新条文就直接用于之前所有行为。"],"kind":"timeline","diagram":[["2026年7月","修订条例公布"],["2026年9月23日","尚未施行"],["2026年10月15日","新条例施行"],["具体行为","核对时间与适用"]],"scenario":"公司在2026年9月就收到争议通知，法务直接用尚未施行的新条例评价此前全部行为。","question":"怎样调整分析？","options":[{"text":"保护期一律从登记证收到之日起15年","why":"混淆起算与上限。"},{"text":"尚未施行意味着中国此前完全没有此类保护","why":"忽略既有制度。"},{"text":"先整理行为时间和适用规则，再判断新旧法及过渡问题","why":"公布和施行之间有时间差。"},{"text":"公布当天自动追溯适用于所有历史行为","why":"没有这种一般结论。"}],"correct":[2],"sources":["chip"],"note":"时间提示：这是已公布、尚未施行的新规。请勿把2026年10月15日以后的规则直接套用到此前行为。","label":"规则与应用"},{"id":"k35","module":5,"pages":[72],"title":"救济与库存：赔偿不是固定倍数","goal":"区分惩罚性赔偿条件与善意库存安排。","body":["2026年修订条例规定，故意侵权且情节严重时，可依法按确定基数的一倍以上五倍以下确定赔偿。并非每个侵权案件都自动五倍赔偿。","不知道且没有合理理由应当知道侵权的经营者，收到明确通知后的既有库存或此前订货，涉及继续商业利用及合理报酬等具体安排。","企业收到通知，应保存采购时间、库存和尽调证据，评估停止、新采购与库存处理，不能把善意当成无限续购许可。"],"kind":"split","diagram":[["主观状态","是否故意或善意"],["情节程度","是否达到严重"],["赔偿计算","基数与法定条件"],["库存处理","通知前后与合理报酬"]],"scenario":"2026年11月，经销商收到明确侵权通知；此前采购时没有合理理由知道侵权。经理计划继续追加同款采购，并声称善意可覆盖全部未来交易。","question":"哪些判断合理？","options":[{"text":"应保留原采购及库存证据并评估合理报酬等条件","why":"事实和条件决定具体处理。"},{"text":"所有库存永远免费销售","why":"忽略通知后规则。"},{"text":"任何侵权都必须赔五倍","why":"惩罚性赔偿有条件和裁量范围。"},{"text":"通知前库存与通知后追加采购需要分别分析","why":"善意库存安排不等于未来采购通行证。"}],"correct":[3,0],"sources":["chip"],"note":"案例假设发生于新条例施行后；真实争议须进一步核对适用条款和事实。","label":"规则与应用"},{"id":"k36","module":5,"pages":[74,75],"title":"ACTA：强化保护也需要程序正当性","goal":"区分政策目标、谈判过程与生效结果。","body":["ACTA旨在强化反假冒等执法合作，但引发透明度、权利平衡等争议。欧洲议会在2012年否决了该协定。","一种国际规则即使追求保护权利，也需要关注公众参与、比例原则与其他合法利益。签署、批准、生效不能混用。","企业评估政策时，应分别问：要解决什么问题、手段是否适当、成本由谁承担、实际法律状态是什么。"],"kind":"flow","diagram":[["保护目标","打击假冒侵权"],["制度设计","执法范围与程序"],["社会审查","透明度与利益平衡"],["法律结果","批准及生效状态"]],"scenario":"行业协会拟推动更强平台执法规则，主张只要有利于权利人，就不必评估误删或中小企业成本。","question":"哪项建议最符合本节启示？","options":[{"text":"保留保护目标，同时评估透明度、误伤和救济机制","why":"政策正当性包含目标与手段。"},{"text":"权利保护目标能自动证明所有措施合理","why":"忽略比例和其他利益。"},{"text":"欧洲议会否决意味着所有反假冒制度无效","why":"单一协定结果不能如此外推。"},{"text":"谈判文件一经发布即对全球企业生效","why":"混淆谈判和法律生效。"}],"correct":[0],"sources":["acta"],"note":"原课件把个别互联网抗议行动归因于ACTA的表述未获充分核实，本学习页不把它作为已证实事实。","label":"制度与政策分析"},{"id":"k37","module":6,"pages":[76,77],"title":"TRIPS：最低标准加上执行机制","goal":"理解国际最低标准与国内救济之间的关系。","body":["TRIPS把多类知识产权的最低保护标准、国内执法要求和成员间争端解决联系起来。各成员仍有各自实施法律和程序。","最低标准不是保护上限，也不是一张全球权利证书。企业诉讼与政府之间的WTO争端属于不同层面。","区域、双边和专门合作安排还可能增加其他义务；分析时要列出适用文件与成员范围，不能把所有国际法院或协议当成同一体系。"],"kind":"tree","diagram":[["国际标准","基本义务"],["国内实施","申请、诉讼与救济"],["成员间争端","政府之间处理"],["其他安排","另查范围和效力"]],"scenario":"企业认为进口国保护不足，准备直接在WTO起诉仿冒商，要求判给自己销售损失。","question":"应如何改进路线？","options":[{"text":"有双边协定就永远无需检查TRIPS","why":"多个义务来源可能并存。"},{"text":"评估当地企业维权渠道，国际层面另考虑政府交涉","why":"私人救济与成员争端不同。"},{"text":"WTO会直接登记商标并执行企业赔款","why":"混淆机构职能。"},{"text":"TRIPS要求各国采用完全一样的诉讼法","why":"最低要求不等于程序完全统一。"}],"correct":[1],"sources":["wto"],"note":"","label":"规则与应用"},{"id":"k38","module":6,"pages":[78,80,81],"title":"从GATT到TRIPS：谈判议题如何扩展","goal":"区分时间线与课件中的历史解释。","body":["GATT体系的谈判最初突出关税和货物贸易，后来议题不断扩展。东京回合为1973—1979年；乌拉圭回合为1986—1994年。","知识产权进入贸易谈判经历了长期磋商，涉及假冒商品、产业利益与南北分歧。1995年WTO成立，TRIPS进入其框架。","理解历史能解释制度选择，但不能把某一利益集团的动机推测，当成每项法律条文的唯一解释。"],"kind":"timeline","diagram":[["1973—1979","东京回合"],["1986—1994","乌拉圭回合"],["1995","WTO成立"],["TRIPS","知识产权纳入贸易框架"]],"scenario":"分析师把东京回合写成1979—1985年，并据此说明TRIPS于1985年随WTO一同建立。","question":"哪项修改正确？","options":[{"text":"GATT与WTO从一开始就是完全同一组织","why":"忽略制度演变。"},{"text":"TRIPS只涉及降低货物关税","why":"其核心为与贸易有关的知识产权。"},{"text":"东京回合改为1973—1979年，WTO成立改为1995年","why":"需分别校正谈判与组织成立节点。"},{"text":"只要结论听起来合理，历史日期不必准确","why":"时间错误会破坏论证。"}],"correct":[2],"sources":["history"],"note":"更正原课件东京回合年份；1980年代的反假冒讨论不等于东京回合。","label":"历史与制度"},{"id":"k39","module":6,"pages":[82,83],"title":"谈判交换：一项协议背后有多种利益","goal":"避免把国家集团看成利益完全一致。","body":["课件讨论发达国家产业诉求、发展中国家的担忧，以及美国301机制等贸易压力。这些属于理解谈判背景的线索。","多边谈判可能跨知识产权、农业、纺织和市场准入进行利益交换；不同国家、行业和消费者的得失未必相同。","商业分析应列出谁得益、谁承担成本、有什么替代方案。单边贸易措施的合法性和适用需要另作具体核查。"],"kind":"split","diagram":[["技术出口方","回收创新投入"],["技术使用方","成本与获取"],["其他行业","市场准入交换"],["政府","发展战略与谈判空间"]],"scenario":"某国药企支持更强保护，仿制药企业担心成本上升，纺织企业则期待出口准入。经理总结“本国企业意见完全一致”。","question":"哪项分析更好？","options":[{"text":"出口企业永远反对知识产权保护","why":"过度概括。"},{"text":"技术进口方在任何条件下都只会受损","why":"忽略创新、投资和其他交换。"},{"text":"一国提出贸易压力就自动决定国际法律效力","why":"压力和合法性需要区分。"},{"text":"分别评估行业与消费者的利益，并说明跨议题交换","why":"国家内部也存在利益差异。"}],"correct":[3],"sources":[],"note":"","label":"历史与政策分析"},{"id":"k40","module":6,"pages":[79],"title":"知识产权与竞争法：授权也有边界","goal":"不能用“行使专利”概括豁免全部行为。","body":["权利人可以依法许可和排除他人，但拥有知识产权并不自动免除竞争法审查。","日本《独占禁止法》第21条与相关指南，需要结合是否属于权利行使及制度目的理解；课件将其概括为全面豁免过于宽泛。","企业应具体审查许可限制、市场影响和正当理由，而非只看合同标题是否叫专利许可。"],"kind":"flow","diagram":[["识别行为","许可及附加限制"],["理解权利","范围与制度目的"],["观察市场","排除与竞争影响"],["具体评估","合法性与理由"]],"scenario":"拥有核心专利的供应商要求客户购买无关产品，并禁止采购竞争产品，经理称“有专利就不受竞争法管”。","question":"哪项回应合理？","options":[{"text":"需审查具体限制和市场效果，专利不提供一概豁免","why":"应分析行为而非只看权利存在。"},{"text":"写进许可合同就天然合法","why":"合同不能排除法律审查。"},{"text":"竞争法意味着专利一律不能收费","why":"收费不当然违法。"},{"text":"专利授权机关已经批准全部商业条款","why":"授权不等于批准后续行为。"}],"correct":[0],"sources":["jftc"],"note":"更正原课件对日本知识产权行使豁免范围的过度概括。","label":"规则与应用"},{"id":"k41","module":6,"pages":[84],"title":"最不发达成员：过渡期有对象和例外","goal":"不要把特殊安排扩展到所有发展中国家。","body":["WTO在2021年延长最不发达成员履行TRIPS部分义务的过渡期：至2034年7月1日，或该成员此前不再具有最不发达国家地位之日，以较早者为准。","一般延长期有例外，TRIPS第3、4、5条不在这一豁免范围内；药品领域还有需要另外核对的专门安排。","这不等于所有发展中国家的全部知识产权都可免费使用，更不当然消除当地已存在的权利。"],"kind":"flow","diagram":[["成员资格","是否属于最不发达"],["时间","2034或更早毕业"],["义务范围","注意3、4、5条例外"],["实际经营","仍查国内法与权利"]],"scenario":"企业准备在一个发展中国家销售仿制产品，仅凭该国收入较低，就认定2034年前不必检查任何专利。","question":"哪项调查不可省略？","options":[{"text":"2034是任何情况下都不会提前变化的日期","why":"退出最不发达地位可能使一般期限提前终止。"},{"text":"核对最不发达成员资格、具体义务安排和当地权利","why":"经济印象不能替代资格与法律分析。"},{"text":"所有发展中国家都自动适用同一期限","why":"适用主体不同。"},{"text":"期限内所有版权与商标自动作废","why":"过渡安排不等于权利统一失效。"}],"correct":[1],"sources":["ldc"],"note":"","label":"规则与应用"},{"id":"k42","module":7,"pages":[85,86,88,89,90],"title":"斯蒂格利茨的批评：观点不是法条","goal":"把政策立场改写成可以检验的问题。","body":["课件引用经济学家约瑟夫·斯蒂格利茨对知识产权全球化的批评：统一的强保护可能不适合所有发展阶段，并影响技术获取与利益分配。","这是政策与经济学讨论，不是法院可以直接适用的法律条文，也不能据此认定任何现行权利无效。","学习时可问：保护是否促进额外创新？成本由谁承担？是否存在许可、公共资助或其他更合适的安排？"],"kind":"tree","diagram":[["政策主张","保护强度应结合情境"],["机制","激励、扩散与定价"],["证据","创新产出与获取变化"],["选择","多种工具比较"]],"scenario":"董事会引用一位经济学家的批评，决定停止履行已签署的技术许可付款义务。","question":"哪项建议正确？","options":[{"text":"只要认为价格太高就不必履约","why":"需要具体法律依据。"},{"text":"因为不是法律，政策研究没有价值","why":"仍能帮助评估改革与商业策略。"},{"text":"政策观点可用于评估制度，但合同及权利义务须另行判断","why":"批评制度不自动免除具体义务。"},{"text":"知名学者的观点自动替代现行法","why":"观点与法律效力不同。"}],"correct":[2],"sources":[],"note":"","label":"学术观点与讨论"},{"id":"k43","module":7,"pages":[87],"title":"药企支出数据：相关性不等于因果","goal":"避免用单一历史数字解释整个行业。","body":["原课件展示药企历史营销和研发支出的比较，并质疑高价格是否必然转化为研发。该数据有年份、样本和分类口径限制。","即使某样本营销支出高于研发，也不能单凭此证明专利从不促进创新，或每一笔营销都没有社会价值。","较好的分析应比较研发产出、价格、利润、失败风险与竞争环境，并说明缺少什么数据。"],"kind":"flow","diagram":[["读数据","年份、样本、口径"],["提出假说","定价如何影响研发"],["排除替代","风险与业务结构"],["谨慎结论","证据支持到哪里"]],"scenario":"投资报告拿某年大药企支出表，宣称“所有专利保护都不会带来任何创新”，没有其他证据。","question":"这段论证应如何改写？","options":[{"text":"把“所有”加粗即可增强可信度","why":"排版不增加证据。"},{"text":"只要数据是数字就一定有因果效力","why":"统计形式不决定因果。"},{"text":"删除年份可让结论更适用现在","why":"隐藏时间会误导。"},{"text":"说明样本和口径，只提出待检验假说并补充研发产出等证据","why":"不能从局部描述直接推出普遍因果。"}],"correct":[3],"sources":[],"note":"原课件中的历史支出数字未作为当前行业统计或确定因果结论使用。","label":"数据与因果分析"},{"id":"k44","module":7,"pages":[91],"title":"静态效率与动态效率：今天和未来的取舍","goal":"把价格可及性与创新激励放在同一张图上。","body":["静态视角关注现有知识如何被广泛、有效使用；更高价格可能让一部分用户无法获得产品。","动态视角关注未来创新：如果研发投入难以回收，可能影响某些项目的开展。但激励强度与真实创新的关系需要证据。","政策评估不能只最大化某一方收入；可以比较许可、期限、例外和其他激励工具对创新及获取的共同影响。"],"kind":"split","diagram":[["今天","价格、可及性与使用"],["未来","研发投入与创新产出"],["平衡工具","许可、例外与激励"],["评价","总福利与分配"]],"scenario":"一家诊断技术企业需回收研发成本，低收入市场又有大量患者买不起。董事会只能在“统一高价”与“立即完全免费”之间争论。","question":"哪些分析能拓宽方案？","options":[{"text":"评估分层定价、许可及公共合作的成本与效果","why":"可以比较更多具体工具。"},{"text":"同时测算研发激励与患者获取变化","why":"两类效果均重要。"},{"text":"只要利润最高就证明社会福利最高","why":"企业利润不是社会福利全部。"},{"text":"任何收费必然使未来创新归零","why":"逻辑错误且缺乏证据。"}],"correct":[0,1],"sources":[],"note":"","label":"经济学分析"},{"id":"k45","module":7,"pages":[92],"title":"知识像烛光：非竞争性不等于没有成本","goal":"理解复制成本与创造成本的区别。","body":["课件用烛光比喻知识：一个人使用某项知识，通常不妨碍另一个人同时使用。这体现知识的非竞争性。","但创造、验证、维护和传播知识仍可能有成本。免费复制不等于研发、产品化与服务全部免费。","数字产品经营需要分别估算首次开发成本、复制成本和持续服务成本，再讨论收费与开放策略。"],"kind":"split","diagram":[["创造","研究、开发和试错"],["复制","新增副本的成本"],["服务","维护、交付与支持"],["使用","多人可同时受益"]],"scenario":"软件公司说“代码可以低成本复制”，客户便要求连同定制开发、云服务和维护都永久免费。","question":"怎样解释最准确？","options":[{"text":"只要开发有成本，任何定价都合理","why":"成本存在不能自动证明全部价格合理。"},{"text":"非竞争性描述知识使用特点，不意味着所有生产与服务成本为零","why":"成本层次需要拆开。"},{"text":"每复制一次知识，原知识就会被消耗一次","why":"不符合非竞争性。"},{"text":"复制成本低，研发必然也低","why":"两个成本不同。"}],"correct":[1],"sources":[],"note":"","label":"经济学分析"},{"id":"k46","module":7,"pages":[93],"title":"最终判断：创新、获取与分配一起看","goal":"形成可复用的商业法律分析顺序。","body":["社会福利不只是权利人收入，也包括消费者收益、创新外溢、执行成本和长期发展。不同群体可能承担不同影响。","商业决策先识别合法边界，再比较可行方案的经济和分配效果。不能因为某方案看起来有社会价值，就忽略有效权利和程序。","完整答案应写明事实假设、适用规则、利益影响和仍需核查的信息；面对不确定性，说明下一步证据比武断结论更有用。"],"kind":"flow","diagram":[["事实","对象、主体、市场、时间"],["规则","权利、许可、例外、程序"],["方案","成本、创新、获取与分配"],["行动","证据、边界与下一步"]],"scenario":"教育平台想把付费课程开放给资源不足的学习者，但内容由多家机构授权，合同只允许收费账号观看。","question":"哪个方案最完整？","options":[{"text":"只考虑平台节约的费用","why":"遗漏权利人和学习者等影响。"},{"text":"因为有版权所以任何公益开放都不可能","why":"许可协商等方案仍可能存在。"},{"text":"先核对许可边界，再协商公益范围并比较成本和覆盖效果","why":"把合法性、可及性和实施条件连接起来。"},{"text":"目标公益就可直接忽略全部合同","why":"目的不能自动消除权利。"}],"correct":[2],"sources":[],"note":"","label":"综合应用"}],"sources":{"paris":["巴黎公约正文","https://www.wipo.int/wipolex/en/text/288514"],"rome":["罗马公约正文","https://www.wipo.int/wipolex/en/text/289757"],"berne":["伯尔尼公约概述","https://www.wipo.int/en/web/treaties/ip/berne/summary_berne"],"phonograms":["日内瓦录音制品公约","https://www.wipo.int/treaties/en/ip/phonograms/summary_phonograms.html"],"wppt":["WPPT","https://www.wipo.int/en/web/treaties/ip/wppt/index"],"beijing":["北京条约概述","https://www.wipo.int/en/web/treaties/ip/beijing/summary_beijing"],"marrakesh":["马拉喀什条约概述","https://www.wipo.int/en/web/treaties/ip/marrakesh/summary_marrakesh"],"singapore":["商标法新加坡条约","https://www.wipo.int/en/web/treaties/ip/singapore/summary_singapore"],"pct":["PCT申请流程","https://www.wipo.int/en/web/pct-system/users/summary"],"genetic":["遗传资源与传统知识条约","https://www.wipo.int/en/web/treaties/ip/gratk/index"],"chip":["2026年修订布图设计条例（2026-10-15施行）","https://www.mee.gov.cn/zcwj/gwywj/202608/t20260804_1163578.shtml"],"case":["最高法（2019）知民终490号","https://ipc.court.gov.cn/zh-cn/news/view-1157.html"],"acta":["欧洲议会否决ACTA","https://www.europarl.europa.eu/news/en/press-room/20120703IPR48247/european-parliament-rejects-acta"],"ldc":["WTO最不发达成员过渡期","https://www.wto.org/english/news_e/news21_e/trip_30jun21_e.htm"],"icj":["国际法院：判决的效力","https://www.icj-cij.org/how-the-court-works"],"wto":["TRIPS协定正文","https://www.wto.org/english/docs_e/legal_e/27-trips.pdf"],"jftc":["日本公取委知识产权使用指南","https://www.jftc.go.jp/en/legislation_gls/imonopoly_guidelines_files/IPGL_Frand.pdf"],"history":["WTO：GATT谈判历史","https://www.wto.org/english/thewto_e/whatis_e/tif_e/fact4_e.htm"]},"sourcePages":[{"page":1,"text":"国际知识产权体系导论\n\n刘孔中教授（德国慕尼黑大学法学博士）\n中国暨南大学／\n中国山东大学兼职讲席教授／\n台湾政治大学／新加坡社科大学／荷兰马斯特里赫特大学兼职教授","units":[]},{"page":2,"text":"开场：我是谁，我在做什么\n\n台湾大学法学学士／法学硕士\n慕尼黑大学法学博士\n台湾“中央研究院”法律学研究所\n2013年，受邀赴新加坡管理大学筹建知识产权中心\n2015年，成立亚洲知识产权与创新研究中心（ARCIALA）\n2017年，从“中央研究院”提前退休，加入新加坡管理大学／中国人民大学\n2021年，ARCIALA在新冠疫情期间关闭\n2025年，从新加坡管理大学提前退休，加入中国暨南大学\n2026年，ARCIALA在暨南大学重新启动","units":[]},{"page":3,"text":"搭建印度与中国之间的桥梁\n\n刘孔中／Uday S. Racherla主编：《中国与印度的创新和知识产权：迷思、现实与机遇》，施普林格出版社，2016年（截至2023年下载4,801次）。\n刘孔中／Uday S. Racherla主编：《中国与印度的创新、经济发展和知识产权：六大经济部门研究》，施普林格出版社，2019年（开放获取：https://library.oapen.org/handle/20.500.12657/23269）。截至2024年1月下载769,443次；截至2025年1月下载868,855次、引用114次；截至2026年1月下载946,514次、引用225次。","units":[]},{"page":4,"text":"提炼亚洲知识产权法：第一套三部曲\n\n刘孔中主编：《亚洲主要法域专利典型案例评注》，香港城市大学出版社，2017年。\n刘孔中主编：《亚洲主要法域版权典型案例评注》，香港城市大学出版社，2019年。\n刘孔中主编：《亚洲主要法域商标典型案例评注》，劳特利奇出版社，2019年。","units":[]},{"page":5,"text":"亚洲知识产权法第二套三部曲\n\n刘孔中／Reto Hilty主编：《商业秘密保护：处于十字路口的亚洲》，克鲁沃出版社，2021年。\n刘孔中／何天翔主编：《亚洲知识产权刑事执法：源起、意义与副作用》，牛津大学出版社，2026年。\n刘孔中／Prashant Reddy主编：《亚洲的可持续发展与知识产权》，劳特利奇出版社，拟于2027年出版。","units":[]},{"page":6,"text":"凸显知识产权法的亚洲视角\n\n刘孔中／Reto Hilty主编：《强制许可：实践经验与未来路径》，马克斯·普朗克亚洲知识产权法系列，施普林格出版社，2015年（截至2023年累计下载33,369次）。\n刘孔中／Reto Hilty主编：《版权人的报酬：新商业模式的监管挑战》，施普林格出版社，2017年（截至2023年累计下载14,050次）。\n刘孔中／Julien Chasse主编：《亚洲贸易协定与知识产权法的未来》，哈特出版社，2019年（亦可开放获取：https://www.bloomsburycollections.com/book/the-future-of-asian-trade-deals-and-ip；截至2023年下载293次）。\n刘孔中／Reto Hilty主编：《标准必要专利、标准制定组织与公平合理无歧视许可：促进互联互通创新的亚洲与全球视角》，劳特利奇出版社，2019年。\n李治安／Reto M. Hilty／刘孔中主编：《人工智能与知识产权》，牛津大学出版社，2021年。","units":[]},{"page":7,"text":"《亚洲主要经济体的知识产权法律与制度：梳理知识产权千丝万缕，共促亚洲和平》（劳特利奇，2022）\n\n亚洲经济体经历了知识产权法律移植、本土化（或内化），以及参与国际知识产权规则制定并表明立场三个阶段。其知识产权法律与制度以独特方式融入各自的发展进程。\n本书讨论亚洲知识产权法的发展困境与努力。\n仅选取与知识产权密切相关的若干亚洲“主要”经济体。\n本书也仅讨论部分主题，有时甚至只聚焦某一个亚洲经济体。这些经济体或多或少反映了亚洲知识产权法律与制度的特点、问题或困境，或者只是我相对更熟悉。\n从中可以提炼出一些亚洲特点与见解，供国际知识产权界参考。\n本书已获得四篇书评。","units":[]},{"page":8,"text":"亚洲主要经济体的\n知识产权法律与制度\n\n梳理知识产权千丝万缕\n共促亚洲和平\n\n刘孔中\n\n本页含参考书封面图片。","units":[]},{"page":9,"text":"解读知识产权法及其与竞争法的冲突与互补：亚洲语境下的全球规范\n\n全球化不等于普遍主义，也不等于整齐划一。\n亚洲拥有独特的产业格局，因此需要不同的法律标准，也有理由采用不同的标准。\n向国际知识产权界提供亚洲见解与富有创造性的反馈。","units":["k01"]},{"page":10,"text":"解读知识产权法\n及其与竞争法的\n冲突与互补\n\n亚洲语境下的全球规范\n\n刘孔中\n\n劳特利奇出版社\n\n本页含参考书封面图片。","units":[]},{"page":11,"text":"那么，你们呢？\n\n你是谁？\n你在哪所院校学习？学习什么专业？\n之后有什么打算？\n你希望从本课程中学到什么？","units":[]},{"page":12,"text":"主动参与国际规则制定\n\n“以国际视野谋划和推动知识产权改革发展，推动构建开放包容、平衡普惠的知识产权国际规则，让创新创造更多惠及各国人民。”\n《知识产权强国建设纲要（2021—2035年）》的工作原则","units":["k01"]},{"page":13,"text":"课程结构\n\n2. 国际和比较版权法\n3. 国际和比较商标法／原产地地理标志\n4. 国际和比较专利法／植物品种保护／国际和比较外观设计法\n5. 国际和比较商业秘密保护\n6. 知识产权的民事与刑事执行\n7. 知识产权用尽与跨境贸易\n8. （传统）文化表达保护／传统知识保护","units":[]},{"page":14,"text":"课程安排\n\n上课时必须关闭手机。\n共七次讲授，最后一次课（第八次）由学生作报告。\n每组报告限时？分钟。\n课程考核：课堂参与占5%（病假须提供医生证明）。小组作业占45%。期末课程作业（ECA）占50%。","units":[]},{"page":15,"text":"不具约束力的国际知识产权条约\n\n1. 工业产权：《巴黎公约》（1883年）\n2. 版权与邻接权\n《伯尔尼公约》（1886年）\n《世界版权公约》（UCC，1952年）\n《罗马公约》（1961年）\n《世界知识产权组织版权条约》（WCT，1996年）\n《世界知识产权组织表演和录音制品条约》（WPPT，1996年）\n《视听表演北京条约》（2012年）\n《关于为盲人、视力障碍者或其他\n印刷品阅读障碍者获得已出版作品提供便利的\n马拉喀什条约》（2016年）","units":["k02","k04","k12"]},{"page":16,"text":"不具约束力的国际知识产权条约\n\n3. 商标\n《商标国际注册\n马德里协定》（1891年）\n《商标国际注册马德里协定\n有关议定书》（1995年）\n《商标注册用商品和服务国际分类尼斯协定》（1957年）\n《商标法条约》（1994年）\n《商标法新加坡条约》（2009年）\n4. 专利与技术性客体\n《专利合作条约》（1978年）","units":["k02","k26","k27"]},{"page":17,"text":"5. 机构安排\n《建立世界知识产权组织公约》\n《乌拉圭回合多边贸易谈判成果最后文件》，或《马拉喀什\n协定》（1995年1月1日）\n6. 名不副实的知识产权条约\n《生物多样性公约》（CBD）\n《保护和促进文化表现形式多样性\n公约》\n《世界知识产权组织知识产权、遗传资源和相关\n传统知识条约》（2024年5月24日通过）\n7. 未能成功的国际知识产权条约","units":["k02","k28"]},{"page":18,"text":"知识产权条约有哪些功能？\n\n提供跨境保护、促进合作，并设立联盟和组织等。\n协调国际知识产权标准，或至少协调其制度框架。\n简化跨国知识产权申请与审查程序，例如避免重复工作。","units":["k01"]},{"page":19,"text":"1.《保护工业产权巴黎公约》的起源\n\n维多利亚女王的丈夫阿尔伯特亲王，在1851年伦敦世界博览会上倡议签订保护工业产权的国际条约。\n比利时、法国、巴西、危地马拉、意大利、葡萄牙、萨尔瓦多、塞尔维亚、西班牙和瑞士于1883年3月20日签署《保护工业产权巴黎公约》，这是第一部知识产权条约。\n公约建立了保护工业产权的联盟，至今仍然有效。\n公约的实体性规定包括：国民待遇、优先权、权利独立（地域性），以及共同规则。","units":["k03"]},{"page":20,"text":"《巴黎公约》的特点\n\n建立国际联盟。\n以共识为基础。\n采取“开放联盟”模式，允许修订并接纳新成员。\n先后在布鲁塞尔（1900年）、华盛顿（1911年）、海牙（1925年）、伦敦（1934年）、里斯本（1958年）、斯德哥尔摩（1967年）和巴黎（1979年）修订。\n截至2022年6月有179个缔约国；截至2023年有180个。\nG.H.C. Bodenhausen：《保护工业产权巴黎公约适用指南》。","units":["k03"]},{"page":21,"text":"不具约束力\n\n《巴黎公约》允许成员将争端提交海牙国际法院（第28条第1款）；但也允许成员在签署本修订文本，或交存批准书、加入书时，声明不受第28条第1款约束（第28条第2款）。\n此外，国际法院的裁判不具约束力，因为缺乏强制执行机制。\n公约尊重成员在国家发展与保护水平方面的差异。\n但是，它未能有效协调各成员的法律。","units":["k04"]},{"page":22,"text":"缔约方与联盟\n\n具有缔结条约能力的国家。\n没有“准入”程序，各成员自行决定是否承认其他“成员”的成员资格。\n巴黎公约联盟、大会（第13条）、执行委员会（第14条）和国际局（第15条）。\n一旦签署最新修订文本，成员对其他成员即负有遵守该文本的义务，无论其他成员是否签署最新修订文本。","units":["k03"]},{"page":23,"text":"苏里南……1975年11月25日；斯德哥尔摩文本：1975年11月25日\n瑞典……1885年7月1日；斯德哥尔摩文本第1—12条：1970年10月9日；第13—30条：1970年4月26日\n瑞士……1884年7月7日；斯德哥尔摩文本第1—12条：1970年4月26日或5月19日³；第13—30条：1970年4月26日\n阿拉伯叙利亚共和国……1924年9月1日；斯德哥尔摩文本：2002年12月13日\n塔吉克斯坦……1991年12月25日；斯德哥尔摩文本：1991年12月25日²\n泰国……2008年8月2日；斯德哥尔摩文本：2008年8月2日\n多哥……1967年9月10日；斯德哥尔摩文本：1975年4月30日\n汤加……2001年6月14日；斯德哥尔摩文本\n特立尼达和多巴哥……1964年8月1日；斯德哥尔摩文本：1988年8月16日\n突尼斯……1884年7月7日；斯德哥尔摩文本：1976年4月12日\n土耳其……1925年10月10日；斯德哥尔摩文本第1—12条：1995年2月1日；第13—30条：1976年5月16日\n土库曼斯坦……1991年12月25日；斯德哥尔摩文本：1991年12月25日²\n乌干达……1965年6月14日；斯德哥尔摩文本：1973年10月20日\n乌克兰……1991年12月25日；斯德哥尔摩文本：1991年12月25日²\n阿拉伯联合酋长国……1996年9月19日；斯德哥尔摩文本：1996年9月19日\n英国……1884年7月7日；斯德哥尔摩文本第1—12条：1970年4月26日或5月19日³；第13—30条：1970年4月26日¹³ ¹⁴ ¹⁵\n坦桑尼亚联合共和国……1963年6月16日；里斯本文本：1963年6月16日；斯德哥尔摩文本第13—30条：1983年12月30日\n美国……1887年5月30日；斯德哥尔摩文本第1—12条：1973年8月25日；第13—30条：1970年9月5日\n委内瑞拉玻利瓦尔共和国……1995年9月12日；斯德哥尔摩文本：1995年9月12日\n越南……1949年3月8日；斯德哥尔摩文本：1976年7月2日\n也门……2007年2月15日；斯德哥尔摩文本：2007年2月15日\n赞比亚……1965年4月6日；里斯本文本：1965年4月6日；斯德哥尔摩文本第13—30条：M〔原文止于此〕","units":["k03"]},{"page":24,"text":"工业产权的范围\n\n专利、实用新型、工业品外观设计、商标、服务标记、商号、货源标记或原产地名称，以及制止不正当竞争（第1条第2款）。\n未提及商业秘密。\n1925年海牙修订明确：成员没有义务保护所列举的全部工业产权。","units":["k05"]},{"page":25,"text":"国民待遇原则\n\n有别于此前的互惠原则。\n适用于联盟任何成员国的国民（第2条第1款）。\n主张权利者在适用本公约时，必须具有某一成员国的国籍；是否同时具有其他国家的国籍并不影响适用。\n不得要求联盟成员国的国民，在请求保护的国家拥有住所或营业所。","units":["k06"]},{"page":26,"text":"视同国民的非国民\n\n联盟以外国家的国民，凡在联盟某一成员国境内设有住所，或\n在其境内设有真实、有效的工业或商业营业所，\n均应享有与联盟成员国国民相同的待遇（第3条）。","units":["k06"]},{"page":27,"text":"国民待遇原则的三个例外\n\n（1）程序性事项可以作不同处理。\n（2）商标不变原则（telle quelle；第6条之五A（1））：凡在原属国正式注册的商标，在符合本条保留规定的前提下，其他联盟成员国应按其原样接受申请并给予保护。“按其原样”“保持原有形式”。","units":["k07"]},{"page":28,"text":"第6条之五：在联盟一国注册的商标在其他成员国的保护\n\nA.（1）凡在原属国正式注册的商标，在符合本条保留规定的前提下，其他联盟成员国应按其原样接受申请并给予保护。在最终注册前，这些国家可以要求提交由原属国主管机关出具的注册证明。该证明无需认证。\n（2）原属国是指申请人设有真实、有效的工业或商业营业所的联盟成员国；如其在联盟境内没有此类营业所，则为其住所所在的成员国；如其在联盟境内没有住所，但具有某一成员国国籍，则为其国籍国。","units":["k07"]},{"page":29,"text":"第三个例外：绝对驳回理由\n\n（3）B. 本条所涉商标，除以下情形外，不得驳回注册或宣告无效：\n1. 商标的性质足以侵犯第三人在请求保护国已经取得的权利。\n2. 商标缺乏任何显著特征，或完全由可在商业中表示商品种类、质量、数量、用途、价值、产地或生产时间的标志、标记组成，或已成为请求保护国的日常用语或诚实、惯常商业实践中的通用标志。\n3. 商标违反道德或公共秩序，尤其是其性质足以欺骗公众。不得仅因商标不符合商标法律中的某项规定，就认定其违反公共秩序，除非该规定本身涉及公共秩序。\n但是，本规定的适用仍须遵守第10条之二。","units":["k07"]},{"page":30,"text":"第4条：优先权\n\nA.（1）任何人在联盟某一成员国正式提出专利申请，或实用新型、工业品外观设计、商标注册申请后，其本人或权利继受人在向其他成员国提出申请时，应在下述规定期限内享有优先权。\nB. 因此，在上述期限届满前向其他成员国提出的后续申请，不因期间发生的行为而失效，特别是其他申请、发明的公布或实施、外观设计复制品的销售，或商标的使用。这些行为也不得产生第三人的任何权利或任何先用权。第三人在作为优先权基础的首次申请日之前已经取得的权利，依联盟各成员国国内法予以保留。","units":["k08"]},{"page":31,"text":"优先权期限\n\n专利与实用新型：12个月。\n外观设计与商标：6个月（第4条C项）。\n自申请日起计算。","units":["k09"]},{"page":32,"text":"优先权制度的演变\n\n1883年文本规定：专利为6个月，外观设计与商标为3个月；外国申请另有1个月宽限期。\n1900年布鲁塞尔修订将专利优先权期限延长至12个月。\n1911年华盛顿修订加入实用新型。\n1925年海牙修订将外观设计与商标的优先权期限延长至6个月。","units":["k09"]},{"page":33,"text":"地域性原则\n\n尽管没有明确表述，地域性原则已深深植根于国际知识产权条约。\n《巴黎公约》第4条和第6条保障在一国取得的专利与商标，独立于在另一国取得的专利与商标。\n《伯尔尼公约》第5条第2款也规定，各国的版权保护相互独立。\n地域性原则允许各主权国家在遵守国际义务的前提下，自主规定无形财产是否获得法律保护，以及保护的条件。\n知识产权仅在授予该权利的国家境内有效。","units":["k10"]},{"page":34,"text":"法院适度、说理充分且逐案偏离地域性原则\n\n自20世纪中叶起，法院在某些法律领域放宽了这一原则。例如，美国法院曾将联邦商标法适用于域外行为。\n“这并不意味着将其限于本地行为在所有案件中都正确，也不意味着将其适用于国境之外在所有案件中都错误。”\n在全球化且相互联通的世界中，地域性原则承受更大压力。因此，“当前监管实践也呈现一种趋势：单方面将本国知识产权实体法制度扩展至域外活动，以突破地域性带来的限制。”\n法院在个案中适度且说理充分地偏离地域性原则，可以具有正当性并获得容许。","units":["k10"]},{"page":35,"text":"第10条之二：不正当竞争\n\n（1）联盟成员国有义务确保这些国家的国民获得有效保护，以制止不正当竞争。\n（2）在工商业事务中违反诚实惯例的任何竞争行为，均构成不正当竞争。\n（3）尤其应禁止下列行为：\n（i）以任何方式使公众对竞争者的营业所、商品或工商业活动产生混淆的行为。\n（ii）在商业活动中作出足以损害竞争者营业所、商品或工商业活动信誉的虚假陈述。\n（iii）在商业活动中使用，可能使公众对商品的性质、制造方法、特点、用途适合性或数量产生误解的标记或陈述。","units":["k11"]},{"page":36,"text":"确定版权限制与例外的“三步检验”\n\n《伯尔尼公约》第9条〔复制权：1. 一般规定；2. 可能的例外；3. 录音和录像〕\n（1）受本公约保护的文学艺术作品的作者，享有授权以任何方式或形式复制其作品的专有权。\n（2）联盟成员国可以通过立法，允许在某些特殊情形下复制上述作品，但这种复制不得与作品的正常利用相冲突，也不得不合理地损害作者的合法利益。\n（3）就本公约而言，任何录音或录像均应视为复制。","units":["k12","k13"]},{"page":37,"text":"邻接权的国际条约\n\n《罗马公约》（1961年）：《保护表演者、录音制品制作者和广播组织的国际公约》，1961年10月26日在罗马订立。\n《罗马公约》在世界知识产权组织（WIPO）、联合国教科文组织（UNESCO）和国际劳工组织（ILO）的主持下形成。\n可能由于三个国际组织之间难以妥协，《罗马公约》从未修订，其20年的保护期因而显得不足。\n共有97个成员（不包括中国和新加坡）。","units":["k14"]},{"page":38,"text":"第5条：受保护的录音制品〔1. 制作者的保护连接点；2. 同时出版；3. 排除某些标准的权利〕\n\n1. 满足下列任何条件时，缔约国应给予录音制品制作者国民待遇：（a）制作者为另一缔约国国民（国籍标准）；（b）声音首次在另一缔约国固定（固定地标准）；（c）录音制品首次在另一缔约国出版（出版地标准）。\n2. 录音制品首次在非缔约国出版，但在首次出版后30日内也在某一缔约国出版的（同时出版），应视为首次在该缔约国出版。\n3. 任何缔约国均可向联合国秘书长交存通知，声明不适用出版地标准，或者不适用固定地标准。","units":["k15"]},{"page":39,"text":"第6条：受保护的广播〔1. 广播组织的保护连接点；2. 保留权〕\n\n1. 满足下列任一条件时，缔约国应给予广播组织国民待遇：（a）广播组织总部位于另一缔约国；（b）广播由位于另一缔约国的发射台播出。\n2. 任何缔约国均可向联合国秘书长交存通知，声明仅在广播组织总部位于另一缔约国，且广播由位于同一缔约国的发射台播出时，才保护该广播。","units":["k15"]},{"page":40,"text":"第13条：广播组织的最低限度权利\n\n广播组织应享有授权或禁止下列行为的权利：\n（a）转播其广播。\n（b）固定其广播。\n（c）复制：（i）未经其同意制作的广播固定物；（ii）依第15条制作的广播固定物，但复制目的不同于该条所规定的目的。\n（d）在公众支付入场费即可进入的场所，向公众传播其电视广播。该权利的行使条件，由请求保护国的国内法规定。\n最低保护期：20年。","units":["k14","k16"]},{"page":41,"text":"第4条：受保护的表演及表演者的保护连接点\n\n满足下列任何条件时，缔约国应给予表演者国民待遇：\n（a）表演发生在另一缔约国。\n（b）表演被收录于受本公约第5条保护的录音制品中。\n（c）未固定于录音制品中的表演，通过受本公约第6条保护的广播传播。","units":["k15"]},{"page":42,"text":"表演者的保护\n\n1. 国民待遇。\n2. 广播及向公众传播的权利。\n3. 固定权。\n4. 复制固定物的权利。","units":["k14","k16"]},{"page":43,"text":"第7条第1款：本公约对表演者的保护，应包括制止以下行为的可能性\n\n（a）未经同意，广播其表演或向公众传播其表演，但所使用的表演本身已为广播表演，或传播以固定物为来源的除外。\n（b）未经同意，固定其尚未固定的表演。\n（c）未经同意，复制其表演的固定物，并具有下列情形：\n（i）原始固定物本身未经其同意制作。\n（ii）复制目的不同于\n表演者同意的目的。\n（iii）原始固定物依照第15条制作，而复制目的不同于该条所规定的目的。","units":["k16"]},{"page":44,"text":"5. 获得一次性合理报酬的权利（强制许可）\n\n第12条规定：“为商业目的出版的录音制品或其复制品，如直接用于广播或向公众传播，使用者应向表演者、录音制品制作者，或双方支付一次性合理报酬。在有关各方未达成协议时，国内法可以规定该报酬的分配条件。”","units":["k17"]},{"page":45,"text":"表演者的保护\n\n第14条：最低保护期限\n本公约规定的保护期，至少应持续至自下列事件发生之年年末起算的20年期间届满：\n（a）对于录音制品及其中收录的表演，自固定发生之年起算。\n（b）对于未收录于录音制品中的表演，自表演发生之年起算。\n（c）对于广播，自广播发生之年起算。","units":["k14"]},{"page":46,"text":"杂耍与马戏表演者\n\n任何缔约国均可通过国内法律法规，将本公约提供的保护扩展至不表演文学或艺术作品的艺人（《罗马公约》第9条）：例如杂耍、马戏、魔术，以及体育竞赛、电子游戏。\n中国《著作权法》：本法所称的作品，是指文学、艺术和科学领域内具有独创性并能以一定形式表现的智力成果，包括：\n（三）音乐、戏剧、曲艺、舞蹈、杂技艺术作品（第3条）。","units":["k18"]},{"page":47,"text":"第15条：允许的例外〔1. 特定限制；2. 与版权相对应的限制〕\n\n1. 任何缔约国均可就本公约保障的保护规定以下例外：（a）私人使用；（b）报道时事时使用简短片段；（c）广播组织利用自身设备、为自身广播制作的临时固定物；（d）仅为教学或科学研究目的使用。2. 无论本条第1款如何规定，任何缔约国均可对表演者、录音制品制作者和广播组织的保护，规定与其对文学艺术作品版权保护所设限制相同类型的限制。但是，只有在与本公约相容的范围内，才能规定强制许可。","units":["k18"]},{"page":48,"text":"录音制品制作者的复制权与录音制品的形式要求\n\n录音制品制作者应享有授权或禁止直接或间接复制其录音制品的权利（第10条）。\n如果某缔约国国内法要求履行一定手续，作为保护录音制品制作者、表演者或双方相关权利的条件，只要已出版录音制品的所有商业流通复制品或其包装上，标有℗符号和首次出版年份，并以足以合理提示权利保护主张的方式放置，即视为手续已履行。如果复制品或包装没有通过姓名、商标或其他适当标识指明制作者或其被许可人，声明还应包括制作者权利所有人的姓名；此外，如果没有指明主要表演者，声明还应包括依固定发生国法律享有这些表演者权利之人的姓名（第11条）。","units":["k19"]},{"page":49,"text":"《保护录音制品制作者防止未经许可复制其录音制品公约》（《日内瓦录音制品公约》，1973年生效）\n\n世界知识产权组织与国际劳工组织、联合国教科文组织共同负责管理本公约。\n公约要求各缔约国保护另一缔约国国民中的录音制品制作者，禁止未经其同意制作复制品；禁止为向公众发行而制作或进口此类复制品；并禁止向公众发行此类复制品。\n“录音制品”指纯粹的声音固定物，不包括电影或录像带的音轨，其形式可以是唱片、磁带等。\n为获得本公约保护，录音制品的复制品须载有专用于录音制品的版权声明，包括录音制品版权符号“℗”。","units":["k19","k20"]},{"page":50,"text":"版权、其他专门权利、反不正当竞争法或刑事制裁\n\n保护期自录音制品首次固定或首次出版之日起，至少为20年。（但越来越多国家的法律规定50年的保护期。）\n第3条：缔约国的实施方式。本公约的实施方式由各缔约国国内法规定，并应包括以下一种或多种方式：通过授予版权或其他专门权利提供保护；通过反不正当竞争法提供保护；通过刑事制裁提供保护。\n共有81个成员（包括中国，但不包括新加坡）。","units":["k20"]},{"page":51,"text":"第6条：保护的限制\n\n通过版权、其他专门权利或刑事制裁提供保护的缔约国，可以对录音制品制作者的保护规定与文学艺术作品作者保护所允许的限制相同类型的限制。但是，除非同时满足以下全部条件，否则不得规定强制许可：\n（a）复制仅用于教学或科学研究。\n（b）许可仅对授予许可的主管机关所在缔约国境内的复制有效，不得扩展至复制品的出口。\n（c）依许可进行复制，应支付由该机关确定的合理报酬；确定时应特别考虑拟制作的复制品数量等因素。","units":["k20"]},{"page":52,"text":"《世界知识产权组织表演和录音制品条约》（WPPT，1996年通过，2002年生效）\n\n1. 保护期至少为50年。\n2. 享有和行使本条约规定的权利，不得以履行任何形式手续为条件。\n3. 缔约方必须对以下行为提供法律救济：规避表演者或录音制品制作者为行使权利所采用的技术措施（如加密）；删除或篡改权利管理所需信息，例如识别表演者、表演、录音制品制作者和录音制品本身的数据。这些“权利管理信息”用于许可、使用费的收取与分配等管理活动。\n4. 条约设立缔约方大会，主要负责条约的维持与发展事项，并将与条约有关的行政事务交由世界知识产权组织秘书处处理。","units":["k21"]},{"page":53,"text":"《视听表演北京条约》（2012年）\n\n《北京条约》于2020年4月28日生效，使《罗马公约》中的视听表演者保护适应数字时代并得到更新。这些更新补充了《世界知识产权组织表演和录音制品条约》的规定。\n条约涵盖电影、电视等不同媒体中的演员表演，也包括音乐表演被录制于DVD或其他视听载体中的音乐家。\n对于固定于视听录制品中的表演，条约赋予表演者四项经济权利：（i）复制权；（ii）发行权；（iii）出租权；（iv）提供给公众的权利。","units":["k22"]},{"page":54,"text":"条约也赋予表演者精神权利\n\n对于尚未固定的现场表演，条约赋予三类经济权利：（i）广播权，但转播除外；（ii）向公众传播权，但广播表演除外；（iii）固定权。\n条约赋予两项精神权利：\n要求表明其表演者身份的权利，但因表演的使用方式而必须省略的除外。\n考虑到视听录制品的性质，反对任何有损表演者声誉的歪曲、篡改或其他修改的权利。","units":["k23"]},{"page":55,"text":"授权权利与获得合理报酬的权利\n\n条约规定，表演者有权授权广播或向公众传播其固定于视听录制品中的表演。但是，缔约方可以通知，以获得合理报酬的权利替代授权权利，适用于直接或间接将此类表演用于广播或向公众传播的情形。\n任何缔约方均可限制该权利，或在对条约作出保留的前提下拒绝给予该权利。在某缔约方作出保留的情形和范围内，其他缔约方可以不向该保留方给予国民待遇，即适用“互惠”（第11条）。","units":["k17","k24"]},{"page":56,"text":"《关于为盲人、视力障碍者或其他印刷品阅读障碍者获得已出版作品提供便利的条约》（2016年）\n\n2013年6月27日，在马拉喀什举行的世界知识产权组织外交会议闭幕时签署；2016年9月30日生效。\n该条约是少数要求缔约方必须设置版权专有权例外，而非仅允许设置例外的国际文书之一。\n第4条第1款（a）：缔约方应在本国版权法中，对复制权、发行权以及《世界知识产权组织版权条约》（WCT）规定的向公众提供权设置限制或例外，便利受益人获得无障碍格式版作品。国内法中的限制或例外，应允许为将作品转换为便于受益人阅读的替代格式而作出必要修改。","units":["k25"]},{"page":57,"text":"强制规定无障碍格式版的跨境交换\n\n该条约不同于早期国际知识产权条约，因为它要求各国制定规定，便利受版权保护作品的跨境获取。\n第5条第1款：缔约方应规定，如果无障碍格式版依据限制或例外，或依法律规定制作，授权实体可以向另一缔约方的受益人或授权实体发行或提供该无障碍格式版。\n关于第5条第1款的议定声明：进一步明确，本条约中的任何规定均不缩小或扩大其他条约所规定的专有权范围。","units":["k25"]},{"page":58,"text":"3.《商标法条约》（1994年）\n\n世界知识产权组织自1989年开始起草关于商标的《巴黎公约补充条约》，但后来认识到，处理程序性事项更为现实。因此，1994年10月订立的《商标法条约》聚焦程序事项，将实体问题留给《与贸易有关的知识产权协定》（TRIPS）。\n1996年8月1日生效；截至2020年有54个缔约成员。\n条约协调并简化国家和区域商标注册的行政程序，使各成员的程序更方便使用、更一致，涵盖商标申请、注册后变更和续展。\n六种正式语文：英语、法语、西班牙语、阿拉伯语、中文和俄语（第24条）。","units":["k26"]},{"page":59,"text":"世界知识产权组织《商标法新加坡条约》（STLT，2009年）\n\n该条约由世界知识产权组织于2006年通过，在1994年《商标法条约》基础上，协调并更新各成员的商标注册与许可程序，旨在便利国际商标保护。\n允许电子通信，对错过期限提供救济，规定许可备案，并允许声音、全息图等非传统商标注册。\n2009年生效。","units":["k26"]},{"page":60,"text":"《专利合作条约》（PCT）的软法性质\n\n第59条：在不违反第64条第5款的前提下，两个或两个以上缔约国关于本条约或实施细则解释、适用的争端，如无法通过谈判解决，任何争端当事国均可依《国际法院规约》向国际法院提出申请，除非有关国家同意采用其他解决方式。第64条第5款允许任何国家声明不受第59条约束。\n任何国家均可声明不受第二章“国际初步审查”的规定约束（第64条第1款）。","units":["k04","k27"]},{"page":61,"text":"5. 机构安排\n\n5.1.《建立世界知识产权组织公约》\n世界知识产权组织的起源可追溯至1883年和1886年：《保护工业产权巴黎公约》和《保护文学和艺术作品伯尔尼公约》分别规定设立“国际局”。\n两个国际局于1893年合并，1970年依据《建立世界知识产权组织公约》，由世界知识产权组织取代。\n5.2.《乌拉圭回合多边贸易谈判成果最后文件》，或《马拉喀什协定》（1995年1月1日）。","units":["k28"]},{"page":62,"text":"6. 名不副实的知识产权条约\n\n《生物多样性公约》（CBD）：旨在保护生物多样性、促进其可持续利用，并确保公平分享遗传资源带来的惠益（1993年生效）。《保护和促进文化表现形式多样性公约》（2007年3月18日生效）。但它们属于知识产权条约吗？","units":["k29"]},{"page":63,"text":"名不副实的知识产权条约\n\n《世界知识产权组织知识产权、遗传资源和相关传统知识条约》（2024年5月24日通过）；美国和中国并非签署国。\n第1条：本条约的目标是：\n（a）提高专利制度在涉及遗传资源及其相关传统知识方面的有效性、透明度和质量。\n（b）防止对涉及遗传资源及其相关传统知识、不具备新颖性或创造性的发明错误授予专利。\n第3条：披露要求。\n第4条：不溯及既往。\n第5条：制裁与救济。\n第6条：信息系统。","units":["k29"]},{"page":64,"text":"未能成功的知识产权条约\n\n《关于集成电路的知识产权条约》\n自20世纪60年代半导体产业兴起以来，美国一直处于领先地位。\n芯片布图或拓扑图（芯片设计）因芯片具有技术功能而无法获得版权法保护；专利保护则需要漫长的审查。\n因此，美国芯片制造商，尤其是英特尔和半导体产业协会，游说制定补救性立法。\n随后，美国颁布了1984年《半导体芯片保护法》（SCPA）。\n尽管该法编入《美国法典》第17编“版权”，它既不是版权法，也不是专利法。","units":["k30"]},{"page":65,"text":"美国如堂吉诃德般引领国际行动\n\n采取“胡萝卜加大棒”的方式，促使外国承认并提供保护。\n日本、欧盟、印度、韩国、澳大利亚、中国大陆和台湾等主要经济体，以及较小经济体，均广泛仿效了这项立法。\n美国推动缔结国际条约，最终促成1989年《华盛顿关于集成电路的知识产权条约》（IPIC，共20条）。","units":["k30"]},{"page":66,"text":"仅有三个法域批准或加入\n\n《TRIPS协定》第二部分第6节“集成电路布图设计（拓扑图）”中的第35条，吸收了IPIC的许多规定，包括第2—7条、第12条和第16条第3款，但不包括第6条第3款。\n然而，仅波斯尼亚和黑塞哥维那、埃及、圣卢西亚三个法域批准或加入IPIC，因此该条约尚未生效。\nIPIC第6条第3款广泛承认为保障自由竞争及防止权利人滥用而实施强制许可，这是该条约未能吸引足够成员以生效的重要原因之一。","units":["k31"]},{"page":67,"text":"在最大的芯片设计国美国，意义有限\n\n登记的集成电路布图设计很少。\n\n年份\n\n掩膜作品数\n\n2010—2022年，美国版权局共登记646件掩膜作品。\n\n没有法院判决。\n\n芯片制造商申请和取得的专利，远多于集成电路布图设计。\n\n图表转写（原课件）：年份2021、2020、2019、2018、2017、2016、2015、2014、2013、2012；对应MW数量33、0、20、156、27、25、28、84、279、203。此为课件历史统计，未独立核实口径，不作为现行数量结论。","units":["k32"]},{"page":68,"text":"在最大的芯片制造地区台湾，意义有限\n\n台湾于1995年制定《积体电路电路布局保护法》，仅在2002年修订过一次。\n该法主要为履行《TRIPS协定》第35—37条及满足美国贸易要求而制定，似乎与台湾资讯与通信产业的实际需求关联不大。\n2013—2022年，仅有1,045件集成电路布图设计登记。\n该法未产生实际应用，因而也缺乏实际意义。没有法院判决适用该法。","units":["k32"]},{"page":69,"text":"在中国大陆，意义有限\n\n集成电路布图设计的专门权利“在司法实践中运行不佳，原因在于法院对其权利配置模式存在混淆”。\n权利人越来越少依赖这一专有权。\nLiu Jianchen：《从排他到获得报酬：集成电路布图设计权利配置模式的演变》（中文文献）。","units":["k32"]},{"page":70,"text":"“锂电池保护芯片”集成电路布图设计侵权案\n\n最高人民法院（2019）最高法知民终490号民事判决\n赛芯公司申请登记名称为“集成控制器与开关管的单芯片负极保护的锂电池保护芯片”的集成电路布图设计， 认为深圳裕昇公司未经许可，复制、销售的芯片与涉案集成电路布图设计实质相同，侵害了涉案集成电路布图设计专有权，故诉至广东省深圳市中级人民法院。\n一审法院认为，经鉴定，被诉侵权芯片与涉案布图设计具有独创性的部分实质相同，构成侵权，判决赔偿赛芯公司经济损失50万元；裕昇公司不服，提起上诉称：涉案布图设计图样的纸件不清晰，不应得到保护；不能以芯片样品确定布图设计专有权的保护范围，且涉案布图设计不具有独创性。\n最高人民法院经审理认为，集成电路布图设计的保护并不以公开布图设计的内容为条件。\n集成电路布图设计的保护对象是为执行某种电子功能而对于元件、线路所作的具有独创性的三维配置，对于独创性的证明，不能过分加大权利人的举证责任。权利人主张其布图设计的三维配置整体或者部分具有独创性应受保护时，应当对其独创性进行解释或者说明，然后由被诉侵权人提供相反证据，在此基础上综合判断该布图设计的三维配置是否具备独创性。","units":["k33"]},{"page":71,"text":"集成电路布图设计保护条例（2001年4月2日国务院令第300号公布, 2026年7月23日国务院令第842号修订）\n\n第二十二条　申请布图设计登记，应当提交：（三）布图设计的独创性声明；\n第二十四条　独创性声明应当指明布图设计具有独创性的设计区域、设计要点以及相应功能。\n第十一条　布图设计权利人享有下列专有权：\n（一）对受保护的布图设计的全部或者其中任何具有独创性的部分进行复制；\n（二）将受保护的布图设计、含有该布图设计的集成电路或者含有该集成电路的物品投入商业利用。\n第十七条　布图设计专有权的保护期为10年，自布图设计登记申请之日或者在世界任何地方首次投入商业利用之日起计算，以较前日期为准。但是，无论是否登记或者投入商业利用，布图设计自创作完成之日起15年后，不再受本条例保护。","units":["k34"]},{"page":72,"text":"1倍以上5倍以下赔偿\n\n第四十六条　侵犯布图设计专有权的赔偿数额按照权利人因被侵权所受到的实际损失或者侵权人因侵权所获得的利益确定；权利人的损失或者侵权人获得的利益难以确定的，参照该布图设计许可使用费的倍数合理确定。对故意侵犯布图设计专有权，情节严重的，可以在按照上述方法确定数额的1倍以上5倍以下确定赔偿数额。\n第四十七条　在获得含有受保护的布图设计的集成电路或者含有该集成电路的物品时，不知道也没有合理理由应当知道其中含有非法复制的布图设计，而将其投入商业利用的，不视为侵权。\n前款行为人得到其中含有非法复制的布图设计的明确通知后，可以继续将现有的存货或者此前的订货投入商业利用，但应当向布图设计权利人支付合理的使用费。","units":["k35"]},{"page":73,"text":"为什么？\n\n该产业不需要法律保护。\n技术密集：极紫外光刻（EUV）／深紫外光刻（DUV）。\n资本密集限制了参与者数量。\n例如，台积电2024年资本支出预算为280亿—320亿美元，2025年最高达370亿美元。\n台积电将在美国投资2,000亿美元，并获得美国联邦政府66亿美元补助的支持。\n全球仅有少数芯片制造商。\n小偷小摸者无法从事芯片盗版。","units":["k32"]},{"page":74,"text":"《反假冒贸易协定》（ACTA）\n\n该协定旨在建立针对假冒商品、仿制药及互联网版权侵权的国际法律框架，并拟在世界贸易组织（WTO）、世界知识产权组织（WIPO）等现有机制之外设立新的管理机构。\n据称，美国电影协会（MPAA）和国际商标协会（INTA）等组织对ACTA议程具有重大影响。\n谈判秘密进行，非政府组织、发展中国家和公众被排除在外。\nACTA拟要求对“煽动、帮助及教唆”某些犯罪施加刑罚，包括“至少在故意进行商业规模的商标假冒及版权或相关权盗版的情况下”。","units":["k36"]},{"page":75,"text":"多亏了维基解密\n\n2008年5月，与ACTA谈判有关的讨论文件和其他材料被上传至维基解密。\n欧洲各地爆发广泛抗议。欧洲议会报告员Kader Arif辞职；继任者、英国欧洲议会议员David Martin也建议议会否决ACTA。\n谷歌关闭一天以示抗议。\n2012年7月4日，欧洲议会以478票反对、39票赞成、165票弃权的悬殊结果否决该协定。","units":["k36"]},{"page":76,"text":"具有约束力的国际知识产权法\n\n《与贸易有关的知识产权协定》（TRIPS，1994年）。\n多边自由贸易协定。\n双边自由贸易协定。\n欧洲统一专利协定（2023年6月1日起运行）。","units":["k37"]},{"page":77,"text":"TRIPS的起源\n\n现有知识产权条约的“不足”。\n不具约束力。\n南北冲突使现有知识产权条约无法修订。\n缺乏执行机制，无法应对全球范围内猖獗的盗版。\n现有条约未涵盖商业秘密、数据库等。\n需要新的平台或途径，制定新的国际知识产权条约。","units":["k04","k37"]},{"page":78,"text":"《关税与贸易总协定》（GATT）\n\n高关税被认为是导致第二次世界大战的因素之一。因此，1948年订立了《关税与贸易总协定》（GATT）。\nGATT同样缺乏可执行性。\nGATT中与知识产权有关的条款很少：\n第9条第6款规定：缔约方应相互合作，防止以歪曲产品真实原产地的方式使用商号，损害缔约方领土内、受其法律保护的产品独特地区名称或地理名称。\n第20条第（4）项规定：……本协定不得解释为阻止任何缔约方采取或实施为确保遵守与本协定不相抵触的法律法规所必需的措施，包括有关……专利、商标和版权保护，以及防止欺诈行为的措施。","units":["k38"]},{"page":79,"text":"亚洲主要经济体以专门条款豁免知识产权的行使\n\n亚洲主要经济体从竞争法建立之初，无论是二战后不久（如日本1947年《禁止私人垄断及确保公平交易法》），还是20世纪90年代，就以专门条款将知识产权行使排除于竞争法审查之外；欧盟和美国没有此类专门条款。日本该法第21条规定无条件豁免：“本法规定不适用于可认定为行使《著作权法》《专利法》《实用新型法》《外观设计法》或《商标法》所规定权利的行为。”韩国逐字沿用了这一规定。\n另一方面，台湾以“正当行为”、印度以“必要的合理条件”规定了较模糊的附条件豁免。\n中国大陆：专利权的滥用由《反垄断法》处理。","units":["k40"]},{"page":80,"text":"GATT东京回合（1979—1985年）\n\n1982年11月29日《部长宣言》作出《关于假冒商品贸易的决定》，指示GATT理事会“研究假冒商品问题，确定在GATT框架下共同打击商业假冒是否有效；如果认为有效，则提出具体措施”。\nGATT于1984年成立假冒商品贸易专家组。\n专家组经过六次讨论，于1985年10月9日报告：盗版商品贸易是严重问题，《巴黎公约》无法防止。专家组不确定GATT是否为打击盗版的适当机构。","units":["k38"]},{"page":81,"text":"乌拉圭回合\n\n始于1986年9月。\n美国、日本等知识产权输出国主张将知识产权纳入国际贸易谈判；印度、巴西和阿根廷等发展中国家则反对。\n哥伦比亚和瑞士提出获得多数支持的文本，题为《与贸易有关（包括假冒商品贸易）的知识产权协定》（TRIPS），使国际贸易组织处理知识产权问题获得正当性。","units":["k38"]},{"page":82,"text":"以多边主义约束美国单边主义\n\nTRIPS与农业问题，是决定乌拉圭回合谈判成败的关键。发展中国家虽然担心加强知识产权保护会阻碍技术传播、提高农产品和药品价格，但仍倾向于通过多边协定和即将成立的“经济联合国”（WTO），应对美国单边贸易制裁，例如1988年《关税法》第301条。\n根据澳大利亚的建议，无须创设全新的国际知识产权条约，而应采取渐进方式：“伯尔尼加强版”和“巴黎加强版”。\n欧洲共同体与美国提出《TRIPS协定》草案。","units":["k39"]},{"page":83,"text":"TRIPS得以达成的原因\n\n对工业化成员而言，TRIPS的潜在利益超过彼此分歧。\n对发展中成员而言：\n1. WTO各项协定带来的其他利益，尤其是农业\n与纺织品配额。\n2. 一揽子挂钩谈判不允许只挑选有利条款。\n3. 过渡宽限期。\n4. 工业化成员承诺提供技术援助，并\n保护传统知识。\n5. 争端解决机构（DSB）可以缓解美国制裁的威胁。\n6. 在日内瓦谈判的成本极高，无法长期参与；\n仅有10个发展中经济体派出代表团。","units":["k39"]},{"page":84,"text":"具有约束力的国际知识产权法\n\n《TRIPS协定》并非以贸易便利化为目标。\n过渡宽限期届满后实行“一刀切”。不过，最不发达国家（LDC）的过渡期不断延长，最新期限为2034年7月1日。\nWTO还有许多其他协定，均以促进贸易为目标，包括政府采购、贸易便利化、民用航空器贸易、基础电信服务、服务贸易、信息技术、货物贸易中的农业、反倾销、海关估价、1947年GATT、进口许可、装运前检验、原产地规则、保障措施、补贴及技术性贸易壁垒等协定。","units":["k41"]},{"page":85,"text":"曾位列影响力第四的经济学家如何看待专利与TRIPS？\n\n按学术引用量衡量，约瑟夫·斯蒂格利茨曾位列世界最有影响力经济学家第四名；2011年入选《时代》杂志全球最具影响力100人。\n斯蒂格利茨的研究聚焦收入分配、资产风险管理、公司治理和国际贸易。\n著作包括：《让全球化发挥作用：走向全球正义的下一步》（2007年）和《不平等的代价》（2012年），两书均登上《纽约时报》畅销书榜；《创造学习型社会：增长、发展与社会进步的新路径》（2014年）；《大分化：不平等社会及其应对》（2015年）；《重写美国经济规则：增长与共同繁荣议程》（2015年）；《欧元：共同货币如何威胁欧洲的未来》（2016年）；《重新审视全球化及其不满：特朗普时代的反全球化》（2017年）。","units":["k42"]},{"page":86,"text":"本页为约瑟夫·斯蒂格利茨的照片。","units":["k42"]},{"page":87,"text":"高价格未必促进创新\n\nTRIPS旨在确保药品价格更高，以促进创新吗？\n激励并未转化为行动。\n美国家庭基金会（Families USA）2001年的论文显示：2000年，美国九大制药公司中有八家的营销支出超过研发支出的两倍；唯一未达到两倍的公司，其营销支出也达研发支出的1.5倍。","units":["k43"]},{"page":88,"text":"简单化的意识形态\n\nTRIPS体现了美国和欧洲的企业利益，压倒发展中世界数十亿人的更广泛利益。\n对内与对外实行双重标准。\nTRIPS以“知识产权保护越强，经济表现越好”的观点为基础。\n特殊利益集团利用简单化的意识形态推进自身诉求。","units":["k42"]},{"page":89,"text":"TRIPS存在治理缺陷\n\n发展中国家的声音太少被听见，特殊利益集团的声音却过于响亮。\n“贸易谈判者的词典里没有公平。”\n贸易协定影响环境、健康和科学的整体进步，但关心这些问题的人却不在谈判桌旁。\n贸易部长往往秘密谈判。\n贸易协定冗长复杂，游说者竭力将谋取自身利益的条款埋入其中。","units":["k42"]},{"page":90,"text":"TRIPS存在治理缺陷\n\nTRIPS是一个错误。\n关键改革是改变知识产权决策的场所与方式。\n场所：世界知识产权组织（WIPO），而非世界贸易组织（WTO）。\n方式：\n1. 依据法治与公平原则。\n2. 向贫穷国家提供法律援助。","units":["k42"]},{"page":91,"text":"过度保护导致垄断与效率损失\n\n垄断不仅可能导致静态效率低下，也可能削弱创新。\n短期内，垄断高价降低社会福利，使经济受损；长期内，如果允许垄断企业打压竞争对手，创新也会放缓，例如微软与网景／RealNetworks之间的竞争。\n专利阻碍知识的传播与使用，并延缓在他人创新基础上开展的后续研究。","units":["k44"]},{"page":92,"text":"以蜡烛比喻知识产权：非竞争性\n\n托马斯·杰斐逊：一支蜡烛点燃另一支蜡烛，并不会减弱自身的光。\n使用不产生额外成本。\n经济效率要求知识能够被自由获取，而知识产权旨在限制使用。\n人们希望，增加的创新能够抵消垄断力量带来的低效率，从而使经济增长更快。","units":["k45"]},{"page":93,"text":"让全球化发挥作用\n\n促进创新与社会正义。\n知识产权本身不是目的，而是实现目的的手段：通过促进创新增进社会福祉。\n我们可以同时实现更多创新与更多社会正义。\n也可以让发展中国家以更低成本实现这一目标。\n知识产权应有助于缩小发展中世界与发达世界之间的知识差距。\n知识产权应使发展中国家能够获得知识与药品。","units":["k46"]}]};
